import React, { useEffect } from 'react';
import ProFeaturePopover from './ProFeaturePopover';

export const LockIcon = ({ className = 'h-3.5 w-3.5' }) => (
  <svg className={className} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true">
    <rect x="4" y="10" width="16" height="10" rx="2" strokeLinecap="round" strokeLinejoin="round" />
    <path d="M7 10V7a5 5 0 0110 0v3" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
);

/**
 * Centered "this is a Pro feature" dialog for locked controls on a screen that
 * is otherwise usable (see Cookie Bar). Closes on backdrop click or Escape.
 */
const ProFeatureModal = ({ isOpen, onClose, title, description }) => {
  useEffect(() => {
    if (!isOpen) {
      return undefined;
    }
    const onKey = (e) => e.key === 'Escape' && onClose();
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [isOpen, onClose]);

  if (!isOpen) {
    return null;
  }

  return (
    <div
      className="fixed inset-0 z-[100000] flex items-center justify-center bg-black/40 px-4"
      role="dialog"
      aria-modal="true"
      onClick={onClose}
    >
      <ProFeaturePopover
        title={title}
        description={description}
        onClose={onClose}
        className="w-[360px]"
      />
    </div>
  );
};

export default ProFeatureModal;
