import React, { useState } from 'react';
import { Toast } from '../../../components/common/Toast';
import { CopyClipboardIcon, DeleteIcon, EditIcon, LegalPageIcon, ViewIcon } from '../../../components/common/SvgIcon';

const TableRow = ({ page, onDelete }) => {
  const [copiedShortcode, setCopiedShortcode] = useState(false);
  const [copiedUrl, setCopiedUrl] = useState(false);

  const copyToClipboard = (text, onSuccess) => {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard
        .writeText(text)
        .then(onSuccess)
        .catch(() => fallbackCopy(text, onSuccess));
    } else {
      fallbackCopy(text, onSuccess);
    }
  };

  const fallbackCopy = (text, onSuccess) => {
    const textArea = document.createElement('textarea');
    textArea.value = text;
    textArea.style.position = 'fixed';
    textArea.style.left = '-999999px';
    document.body.appendChild(textArea);
    textArea.select();
    try {
      document.execCommand('copy');
      onSuccess();
    } catch (err) {
      Toast.error('Failed to copy');
    }
    document.body.removeChild(textArea);
  };

  const copyShortcode = (shortcode) => {
    copyToClipboard(shortcode, () => {
      Toast.success('Shortcode copied!');
      setCopiedShortcode(true);
      setTimeout(() => setCopiedShortcode(false), 2000);
    });
  };

  const copyUrl = (url) => {
    copyToClipboard(url, () => {
      Toast.success('Page URL copied!');
      setCopiedUrl(true);
      setTimeout(() => setCopiedUrl(false), 2000);
    });
  };

  return (
    <tr className="h-[68px] border-b border-[#E4E4E7] hover:bg-gray-50 transition-colors">
      {/* ID */}
      <td className="py-4 px-4">
        <span className="text-sm font-medium text-[#6F6F7B]">#{page.id}</span>
      </td>

      {/* Title */}
      <td className="py-4 px-4">
        <button
          type="button"
          onClick={() => copyUrl(page.view_url)}
          title={copiedUrl ? 'URL copied!' : `Copy URL: ${page.view_url}`}
          className="flex items-center gap-2 text-left group cursor-pointer"
        >
          <div className="w-10 h-10 bg-[#7C3BED]/10 rounded-xl flex items-center justify-center flex-shrink-0">
            <LegalPageIcon />
          </div>
          <div>
            <div className="text-sm font-semibold text-[#17171C] group-hover:text-[#7C3BED] flex items-center gap-1.5">
              {page.title}
              {copiedUrl ? (
                <svg className="w-3.5 h-3.5 text-[#7C3BED]" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M5 13l4 4L19 7"
                  />
                </svg>
              ) : (
                <span className="opacity-0 group-hover:opacity-100 transition-opacity">
                  <CopyClipboardIcon />
                </span>
              )}
            </div>
            <div className="text-xs text-[#6F6F7B]">{page.subtitle || 'Legal Page'}</div>
          </div>
        </button>
      </td>

      {/* Author */}
      <td className="py-4 px-4">
        <span className="text-sm text-[#6F6F7B]">{page.author}</span>
      </td>

      {/* Created At */}
      <td className="py-4 px-4">
        <span className="text-sm text-[#6F6F7B]">{page.created_at}</span>
      </td>

      {/* Shortcode */}
      <td className="py-4 px-4">
        <button
          onClick={() => copyShortcode(page.shortcode)}
          className="inline-flex items-center gap-[10px] px-3 py-1.5 bg-[#7C3BED]/5 hover:bg-[#7C3BED]/10 text-[#7C3BED] rounded-md text-xs font-mono transition-colors"
        >
          <span>{page.shortcode}</span>
          {copiedShortcode ? (
            <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M5 13l4 4L19 7"
              />
            </svg>
          ) : (
            <CopyClipboardIcon />
          )}
        </button>
      </td>

      {/* Actions */}
      <td className="py-4 px-4">
        <div className="flex items-center gap-2">
          {/* View */}
          <a
            href={page.view_url}
            target="_blank"
            rel="noopener noreferrer"
            className="p-2 text-[#6F6F7B] cursor-pointer hover:text-[#7C3BED] hover:bg-[#7C3BED]/5 rounded-xl transition-colors"
            title="View page"
          >
            <ViewIcon />
          </a>

          {/* Edit */}
          <button
            type="button"
            onClick={() => { window.location.hash = `/edit-legal-page/${page.id}`; }}
            className="p-2 text-[#6F6F7B] cursor-pointer hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-colors"
            title="Edit page"
          >
            <EditIcon />
          </button>

          {/* Delete */}
          <button
            onClick={() => onDelete(page.id, page.title)}
            className="p-2 text-[#6F6F7B] cursor-pointer hover:text-red-600 hover:bg-red-50 rounded-xl transition-colors"
            title="Delete page"
          >
            <DeleteIcon />
          </button>
        </div>
      </td>
    </tr>
  );
};

export default TableRow;