import React, { useState } from 'react';
import { Toast } from '../../../components/common/Toast';
import { CopyClipboardIcon, InfoIcon } from '../../../components/common/SvgIcon';

// Tags that need more than "[tag]" to be useful: a line of help, and for enclosing
// tags a complete example to copy instead of the bare tag.
const GUIDED = {
  lp_if: {
    label: '[lp_if region="eu"] … [/lp_if]',
    copy: '[lp_if region="eu"]\nText shown only when "European Union" is ticked in Settings → Regions Served.\n[/lp_if]',
    help: 'Shows the text between the tags only for the regions you serve (Settings → Regions Served). Codes: eu, uk, us, canada, australia; several: region="canada,australia". With no regions ticked, everything shows.',
  },
  // The picker shows and copies the short lp_ names; the long ones keep working.
  legal_pages_cookie_list: {
    label: '[lp_cookie_table]',
    copy: '[lp_cookie_table]',
    help: 'A live table of the cookies found by the cookie scanner, grouped by category. Also works as [legal_pages_cookie_list].',
  },
  legal_pages_manage_consent: {
    label: '[lp_manage_consent]',
    copy: '[lp_manage_consent]',
    help: 'A link that reopens the cookie banner so visitors can change their choice. Also works as [legal_pages_manage_consent].',
  },
  legal_pages_dnsmpi_form: {
    label: '[lp_do_not_sell_form]',
    copy: '[lp_do_not_sell_form]',
    help: 'The "Do Not Sell or Share" opt-out button: turns marketing cookies off on the visitor\'s browser and records it in the consent log. Needs the cookie banner on. Also works as [legal_pages_dnsmpi_form].',
  },
  lp_smart_policy: {
    label: '[lp_smart_policy]',
    copy: '[lp_smart_policy]',
    help: 'A "Third-party services we use" section with a clause for each service found on your site. It updates itself when your site changes.',
  },
};

const fallbackCopy = (text) => {
  const textArea = document.createElement('textarea');
  textArea.value = text;
  textArea.style.position = 'fixed';
  textArea.style.left = '-999999px';
  document.body.appendChild(textArea);
  textArea.select();
  try {
    document.execCommand('copy');
    Toast.success('Shortcode copied!');
  } catch (err) {
    Toast.error('Failed to copy');
  }
  document.body.removeChild(textArea);
};

const copyText = (text) => {
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text)
      .then(() => Toast.success('Shortcode copied!'))
      .catch(() => fallbackCopy(text));
  } else {
    fallbackCopy(text);
  }
};

const AllShortCodes = ({ shortcodes, copyShortcode, loading }) => {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <>
      {loading ? (
        <div className="space-y-4">
          <div className="h-8 bg-gray-200 rounded animate-pulse"></div>
          <div className="h-8 bg-gray-200 rounded animate-pulse"></div>
        </div>
      ) : (
        <>
          {/* Collapsible Header */}
          <button
            onClick={() => setIsOpen(!isOpen)}
            className="w-full flex items-center justify-between group transition-all cursor-pointer px-2 sm:px-0"
          >
            <div className="flex items-center gap-2 sm:gap-3">
              {/* Link Icon */}
              <span className="text-xl sm:text-2xl">🔗</span>
              <h3 className="text-lg sm:text-xl md:text-2xl font-bold text-[#17171C]">
                Available Shortcodes
              </h3>
            </div>
            {/* Chevron Icon */}
            <svg
              className={`w-5 h-5 sm:w-6 sm:h-6 text-gray-600 transition-transform duration-300 flex-shrink-0 ${
                isOpen ? 'rotate-180' : ''
              }`}
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M19 9l-7 7-7-7"
              />
            </svg>
          </button>

          {/* Expandable Content with Smooth Animation */}
          <div
            className={`overflow-hidden transition-all duration-500 ease-in-out ${
              isOpen ? 'max-h-[800px] opacity-100 mt-3 sm:mt-4' : 'max-h-0 opacity-0'
            }`}
          >
            <div className="bg-white">
              <div className="bg-gradient-to-r from-purple-50 to-blue-50 border-l-4 border-[#7C3BED] px-4 py-3 mb-4 sm:mb-6 rounded-r-lg">
                <p className="text-sm sm:text-base text-[#17171C] font-medium flex items-center gap-2">
                {InfoIcon}
                  Click on any shortcode below to copy it
                </p>
              </div>
              
              <div className="space-y-2 sm:space-y-3 max-h-[400px] sm:max-h-[500px] md:max-h-[600px] overflow-y-auto pr-1 custom-scrollbar">
                {Object.keys(shortcodes).map((key) => {
                  const guide = GUIDED[key];
                  return (
                    <button
                      key={key}
                      onClick={() => (guide && guide.copy ? copyText(guide.copy) : copyShortcode(key))}
                      className="w-full px-3 py-3 sm:px-4 sm:py-3.5 md:px-5 md:py-3 text-left font-mono text-[#7C3BED] bg-[#F4F4F5] bg-opacity-50 rounded-xl sm:rounded-2xl transition-colors flex items-center justify-between gap-3 group cursor-pointer hover:bg-opacity-70 active:bg-opacity-90"
                    >
                      <span className="flex min-w-0 flex-col gap-1.5">
                        <span className="self-start text-xs sm:text-sm md:text-xs !bg-[#7C3BED1A] px-1.5 py-1 sm:p-[7px] bg-opacity-10 rounded break-all">
                          {guide && guide.label ? guide.label : `[${key}]`}
                        </span>
                        {guide && (
                          <span className="font-sans text-xs leading-snug text-[#6F6F7B]">{guide.help}</span>
                        )}
                      </span>
                      <span className="flex-shrink-0"><CopyClipboardIcon /></span>
                    </button>
                  );
                })}
              </div>
            </div>
          </div>
        </>
      )}
    </>
  );
};

export default AllShortCodes;