import React from 'react';
import SectionCard from '../../../../components/common/SectionCard';
import { LockIcon } from '../../../../components/common/ProFeatureModal';
export const CATEGORY_OPTIONS = [
  { value: 'functional',   label: 'Functional' },
  { value: 'preferences',  label: 'Preferences' },
  { value: 'statistics',   label: 'Statistics' },
  { value: 'marketing',    label: 'Marketing' },
  { value: 'unclassified', label: 'Unclassified' },
];

// `!` because WP admin's own `select` styles otherwise win.
const CATEGORY_STYLES = {
  functional:   '!bg-emerald-50 !text-emerald-700',
  preferences:  '!bg-sky-50 !text-sky-700',
  statistics:   '!bg-amber-50 !text-amber-700',
  marketing:    '!bg-rose-50 !text-rose-700',
  unclassified: '!bg-gray-100 !text-gray-600',
};

const STORAGE_LABELS = {
  cookie:         'Cookie',
  localstorage:   'Local storage',
  sessionstorage: 'Session storage',
};

export const ScanIcon = () => (
  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#7C3BED" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
    <path d="M3 7V5a2 2 0 0 1 2-2h2M17 3h2a2 2 0 0 1 2 2v2M21 17v2a2 2 0 0 1-2 2h-2M7 21H5a2 2 0 0 1-2-2v-2" />
    <circle cx="11" cy="11" r="4" />
    <path d="m17 17-3.2-3.2" />
  </svg>
);

const secondaryBtn =
  'inline-flex cursor-pointer items-center justify-center rounded-xl border border-[#E4E4E7] bg-white px-3.5 py-[11px] text-sm font-medium text-[#17171C] transition hover:bg-[#FAFAFA] disabled:cursor-not-allowed disabled:opacity-50';
// `!font-bold`: WP admin's button styles otherwise override the weight.
const primaryBtn =
  'inline-flex min-w-[140px] cursor-pointer items-center justify-center rounded-xl bg-[#7C3BED] px-10 py-3 text-sm !font-bold text-white shadow-[0px_4px_14px_-2px_#7C3BED40] transition hover:bg-indigo-700 disabled:cursor-not-allowed disabled:bg-indigo-400';

const noop = () => {};

/**
 * Presentational scan panel (state lives in CookieScanner). With `locked`, the
 * Pro controls stay visible but call `onLocked(feature)` instead of acting.
 */
const ScanPanel = ({
  postTypes = [],
  selectedTypes = [],
  onToggleType,
  state = {},
  cookies = [],
  scanning = false,
  syncing = false,
  onScan,
  onStop,
  onClear,
  onSync,
  onUpdateCookie,
  iframeRef,
  locked = false,
  onLocked = noop,
}) => {
  const detectedServices = Object.keys(state.detected_services || {});
  const activeCookies = cookies.filter((c) => !c.ignored);
  const progress = state.progress || 0;

  return (
    <SectionCard title="Website Cookie Scan" icon={<ScanIcon />} maxHeight="">
      <div className="space-y-6">
        <p className="!text-sm !text-[#6F6F7B]">
          Scan your pages for first-party cookies, local/session storage, and known third-party scripts.
          Found cookies are described automatically using <strong>cookiedatabase.org</strong> (only cookie
          names are sent), so you can list them in your cookie policy and assign them to consent categories.
          Changing a cookie's category by hand stops Sync from overwriting it.
        </p>

        {/* Post types */}
        <div>
          <label className="block text-sm font-medium text-[#17171C] mb-3">Post types to scan</label>
          <div className="flex flex-wrap gap-x-6 gap-y-2">
            {postTypes.map((type) =>
              type.locked ? (
                <button
                  key={type.value}
                  type="button"
                  className="inline-flex cursor-pointer items-center gap-2 text-sm text-[#A1A1AA]"
                  onClick={() => onLocked('post_types')}
                >
                  <input type="checkbox" className="!m-0 pointer-events-none" checked={false} disabled readOnly tabIndex={-1} />
                  {type.label}
                  <span className="text-[#7C3BED]"><LockIcon /></span>
                </button>
              ) : (
                <label key={type.value} className="inline-flex cursor-pointer items-center gap-2 text-sm text-[#17171C]">
                  <input
                    type="checkbox"
                    className="!m-0"
                    checked={selectedTypes.includes(type.value)}
                    disabled={scanning}
                    onChange={() => onToggleType(type.value)}
                  />
                  {type.label}
                </label>
              )
            )}
          </div>
          <p className="!mt-2 !text-xs !text-[#6F6F7B]">
            The homepage and WooCommerce shop pages are always included. Up to 5 recent items per post type are scanned.
          </p>
        </div>

        {/* Status + progress */}
        <div className="rounded-xl bg-[#F4F4F580] p-4">
          <div className="flex flex-wrap items-center justify-between gap-2 text-sm">
            <span className="font-medium text-[#17171C]">
              {scanning
                ? `Scanning ${state.processed || 0} of ${state.total || 0} pages…`
                : state.finished_at
                  ? `Last scan: ${state.finished_at}`
                  : 'No scan has run yet.'}
            </span>
            <span className="text-[#6F6F7B]">
              {activeCookies.length} cookies · {detectedServices.length} services detected
            </span>
          </div>
          <div className="mt-3 h-2 w-full overflow-hidden rounded-full bg-[#E4E4E7]">
            <div className="h-full rounded-full bg-[#7C3BED] transition-all duration-500" style={{ width: `${progress}%` }} />
          </div>
          {scanning && state.current_url && (
            <p className="!mt-2 !text-xs !text-[#6F6F7B] truncate">{state.current_url}</p>
          )}
          {!scanning && state.sync_error && (
            <p className="!mt-2 !text-xs !text-red-600">cookiedatabase.org: {state.sync_error}</p>
          )}
        </div>

        {/* Actions */}
        <div className="flex flex-wrap gap-3">
          {scanning ? (
            <button type="button" className={primaryBtn} onClick={onStop}>Stop Scan</button>
          ) : (
            <button type="button" className={primaryBtn} onClick={onScan} disabled={selectedTypes.length === 0 && postTypes.length > 0}>
              Scan
            </button>
          )}
          {locked ? (
            <>
              <button type="button" className={`${secondaryBtn} gap-2`} onClick={() => onLocked('sync')} disabled={scanning}>
                Sync with cookiedatabase.org
                <span className="text-[#7C3BED]"><LockIcon /></span>
              </button>
              <button type="button" className={`${secondaryBtn} gap-2`} onClick={() => onLocked('clear')} disabled={scanning}>
                Clear Cookies
                <span className="text-[#7C3BED]"><LockIcon /></span>
              </button>
            </>
          ) : (
            <>
              <button type="button" className={secondaryBtn} onClick={onSync} disabled={scanning || syncing || cookies.length === 0}>
                {syncing ? 'Syncing…' : 'Sync with cookiedatabase.org'}
              </button>
              <button type="button" className={secondaryBtn} onClick={onClear} disabled={scanning || cookies.length === 0}>
                Clear Cookies
              </button>
            </>
          )}
        </div>

        {/* Detected third-party services */}
        {detectedServices.length > 0 && (
          <div>
            <label className="block text-sm font-medium text-[#17171C] mb-2">Detected services</label>
            <div className="flex flex-wrap gap-2">
              {detectedServices.map((name) => (
                <span key={name} className="rounded-full bg-[#7C3BED1A] px-3 py-1 text-xs font-medium text-[#7C3BED]">{name}</span>
              ))}
            </div>
          </div>
        )}

        {/* Results */}
        {cookies.length > 0 && (
          <div className="border border-[#E4E4E7] rounded-xl overflow-hidden">
            <div className="max-h-[420px] overflow-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="bg-[#FAFAFA] border-b border-[#E4E4E7]">
                    <th className="text-left px-4 py-3 font-semibold text-[#17171C]">Name</th>
                    <th className="text-left px-4 py-3 font-semibold text-[#17171C]">Service</th>
                    <th className="text-left px-4 py-3 font-semibold text-[#17171C] w-40">Category</th>
                    <th className="text-left px-4 py-3 font-semibold text-[#17171C]">Retention</th>
                    <th className="text-left px-4 py-3 font-semibold text-[#17171C]">Purpose</th>
                    <th className="px-4 py-3 w-20" />
                  </tr>
                </thead>
                <tbody className="divide-y divide-[#E4E4E7]">
                  {cookies.map((cookie) => (
                    <tr key={cookie.id} className={`transition hover:bg-[#FAFAFA] ${cookie.ignored ? 'opacity-50' : ''}`}>
                      <td className="px-4 py-3 align-top">
                        <div className="font-mono text-xs text-[#17171C] break-all">{cookie.name}</div>
                        <div className="text-xs text-[#6F6F7B]">{STORAGE_LABELS[cookie.storage] || cookie.storage}</div>
                      </td>
                      <td className="px-4 py-3 align-top text-[#17171C]">{cookie.service || '—'}</td>
                      <td className="px-4 py-3 align-top">
                        {locked ? (
                          <button
                            type="button"
                            title="Changing the category is a Pro feature"
                            onClick={() => onLocked('category')}
                            className={`inline-flex cursor-pointer items-center gap-1.5 rounded-lg py-1 px-2 text-xs font-medium ${CATEGORY_STYLES[cookie.category] || ''}`}
                          >
                            {CATEGORY_OPTIONS.find((opt) => opt.value === cookie.category)?.label || cookie.category}
                            <LockIcon className="h-3 w-3" />
                          </button>
                        ) : (
                          <select
                            value={cookie.category}
                            onChange={(e) => onUpdateCookie(cookie.id, { category: e.target.value })}
                            className={`!rounded-lg !border-0 !py-1 !pl-2 !pr-7 !text-xs font-medium ${CATEGORY_STYLES[cookie.category] || ''}`}
                          >
                            {CATEGORY_OPTIONS.map((opt) => (
                              <option key={opt.value} value={opt.value}>{opt.label}</option>
                            ))}
                          </select>
                        )}
                        {cookie.auto_sync === false && (
                          <div className="mt-1 text-[11px] text-[#6F6F7B]">
                            Set manually ·{' '}
                            <button
                              type="button"
                              className="cursor-pointer text-[#7C3BED] hover:underline"
                              title="Let Sync update this cookie from cookiedatabase.org again"
                              onClick={() => (locked ? onLocked('category') : onUpdateCookie(cookie.id, { auto_sync: true }))}
                            >
                              Resume sync
                            </button>
                          </div>
                        )}
                      </td>
                      <td className="px-4 py-3 align-top text-[#6F6F7B]">{cookie.retention || '—'}</td>
                      <td className="px-4 py-3 align-top text-[#6F6F7B]">{cookie.purpose || (cookie.synced && !cookie.service ? 'Not in cookiedatabase.org' : '—')}</td>
                      <td className="px-4 py-3 align-top text-right">
                        <button
                          type="button"
                          className="inline-flex cursor-pointer items-center gap-1 text-xs font-medium text-[#7C3BED] hover:underline"
                          onClick={() => (locked ? onLocked('ignore') : onUpdateCookie(cookie.id, { ignored: !cookie.ignored }))}
                        >
                          {cookie.ignored ? 'Restore' : 'Ignore'}
                          {locked && <LockIcon className="h-3 w-3" />}
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {cookies.length > 0 && (
          <p className="!text-xs !text-[#6F6F7B]">
            Add <code className="rounded bg-[#7C3BED1A] px-1.5 py-0.5 text-[#7C3BED]">[legal_pages_cookie_list]</code> to
            your cookie policy page to show these cookies by category (ignored ones are left out). New pages created from
            the GDPR Cookie Policy or Cookie Privacy Policy templates include it already.
          </p>
        )}

        {/* Upsell once the first scan has finished (not while one is running). */}
        {locked && !scanning && state.finished_at && (
          <p className="!m-0 flex items-center gap-2 rounded-xl border border-[#7C3BED33] bg-[#7C3BED0F] px-4 py-3 !text-sm !font-medium !text-[#17171C]">
            <span aria-hidden="true">👑</span>
            <span>
              Your site requires these cookie banners.{' '}
              <a
                href="https://legalpagespro.com/?utm_source=lite-plugin#pricing"
                target="_blank"
                rel="noopener noreferrer"
                className="!font-semibold !text-[#7C3BED] hover:underline"
              >
                Upgrade now
              </a>{' '}
              to add them automatically.
            </span>
          </p>
        )}

        {/* Scan driver: pages load here so their scripts run and set cookies. */}
        {iframeRef && <iframe ref={iframeRef} title="Cookie scan" className="hidden" aria-hidden="true" />}
      </div>
    </SectionCard>
  );
};

export default ScanPanel;
