import React from "react";
import { Toast } from "../../../components/common/Toast";
import { AddressInfoIcon, BusinessInformationIcon, GlobeIcon, SavingIcon, SocialInfoIcon } from "../../../components/common/SvgIcon";
import SectionCard from "../../../components/common/SectionCard";
import FormField from "../../../components/common/FormField";
import ConfirmationModal from "../../../components/common/ConfirmationModal";

const save = `${LEGAL_PAGES.assets_url}/images/icons/save.png`;
const reset = `${LEGAL_PAGES.assets_url}/images/icons/reset.png`;
const deleteIcon = `${LEGAL_PAGES.assets_url}/images/icons/delete.png`;

const REGION_OPTIONS = [
  { value: "eu", label: "European Union (EU / EEA)" },
  { value: "uk", label: "United Kingdom" },
  { value: "us", label: "United States" },
  { value: "canada", label: "Canada" },
  { value: "australia", label: "Australia" },
];

const GeneralInformation = ({ formData, handleInputChange, handleRegionsChange, saving, handleSave, handleReset, isLoading, setIsLoading, handleResetSavedData, showDeleteModal, setShowDeleteModal }) => {

  const fallbackCopy = (text) => {
    const textArea = document.createElement("textarea");
    textArea.value = text;
    textArea.style.position = "fixed";
    textArea.style.left = "-999999px";
    document.body.appendChild(textArea);
    textArea.select();
    try {
      document.execCommand("copy");
      Toast.success("Placeholder copied to clipboard!");
    } catch (err) {
      console.error("Fallback copy failed:", err);
      Toast.error("Failed to copy to clipboard");
    }
    document.body.removeChild(textArea);
  };

  const copyToClipboard = (text) => {
    if (!text) return;
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard
        .writeText(text)
        .then(() => Toast.success("Placeholder copied to clipboard!"))
        .catch((err) => {
          console.error("Failed to copy:", err);
          fallbackCopy(text);
        });
    } else {
      fallbackCopy(text);
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    handleSave();
  };

  const handleResetClick = (e) => {
    e.preventDefault();
    handleReset();
  };

  const handleDeleteClick = (e) => {
    e.preventDefault();
    setShowDeleteModal(true);
  };

  return (
    <form onSubmit={handleSubmit} noValidate>
      <div className="space-y-6 mt-6">
        {/* Business Information */}
        {isLoading ? (
          <SectionCard title="Business Information" icon={<BusinessInformationIcon/>} maxWidth="max-w-[1150px]">
            <div className="space-y-3">
              <div className="h-10 bg-gray-200 rounded animate-pulse"></div>
              <div className="h-10 bg-gray-200 rounded animate-pulse"></div>
              <div className="h-10 bg-gray-200 rounded animate-pulse"></div>
              <div className="h-10 bg-gray-200 rounded animate-pulse"></div>
              <div className="h-10 bg-gray-200 rounded animate-pulse"></div>
            </div>
          </SectionCard>
        ) : (
          <SectionCard
            title="Business Information"
            icon={<BusinessInformationIcon />}
            maxWidth="max-w-[1150px]"
            maxHeight="max-h-[540px]"
          >

            <div className="space-y-3">
              <FormField
                label="Your Site URL"
                name="site_url"
                placeholder="[siteUrl]"
                value={formData.site_url}
                onChange={handleInputChange}
                onCopy={copyToClipboard}
              />
              <FormField
                label="Site / Business Name"
                name="site_name"
                placeholder="[siteName]"
                value={formData.site_name}
                onChange={handleInputChange}
                onCopy={copyToClipboard}
              />
              <FormField
                label="Business Niche"
                name="business_niche"
                placeholder="[businessNiche]"
                value={formData.business_niche}
                onChange={handleInputChange}
                onCopy={copyToClipboard}
              />
              <FormField
                label="Phone Number"
                name="phone_number"
                placeholder="[phoneNumber]"
                value={formData.phone_number}
                onChange={handleInputChange}
                onCopy={copyToClipboard}
                type="tel"
              />
              <FormField
                label="Email Address"
                name="email_address"
                placeholder="[emailAddress]"
                value={formData.email_address}
                onChange={handleInputChange}
                onCopy={copyToClipboard}
              />
            </div>
          </SectionCard>
        )}

        {/* Address Information */}
        {isLoading ? (
          <SectionCard title="Address Information" icon={<AddressInfoIcon />}>
            <div className="space-y-3">
              <div className="h-10 bg-gray-200 rounded animate-pulse"></div>
              <div className="h-10 bg-gray-200 rounded animate-pulse"></div>
              <div className="h-10 bg-gray-200 rounded animate-pulse"></div>
              <div className="h-10 bg-gray-200 rounded animate-pulse"></div>
              <div className="h-10 bg-gray-200 rounded animate-pulse"></div>
              <div className="h-10 bg-gray-200 rounded animate-pulse"></div>
            </div>
          </SectionCard>
        ) : (
          <SectionCard
            maxHeight="max-h-[670px]"
            title="Address Information"
            icon={<AddressInfoIcon />}
          >
            <div className="space-y-3">
              <FormField
                label="Street Name"
                name="street_name"
                placeholder="[streetName]"
                value={formData.street_name}
                onChange={handleInputChange}
                onCopy={copyToClipboard}
              />
              <FormField
                label="City"
                name="city"
                placeholder="[cityName]"
                value={formData.city}
                onChange={handleInputChange}
                onCopy={copyToClipboard}
              />
              <FormField
                label="State"
                name="state"
                placeholder="[stateName]"
                value={formData.state}
                onChange={handleInputChange}
                onCopy={copyToClipboard}
              />
              <FormField
                label="Country Name"
                name="country_name"
                placeholder="[countryName]"
                value={formData.country_name}
                onChange={handleInputChange}
                onCopy={copyToClipboard}
              />
              <FormField
                label="Zip/Postal Code"
                name="zip_code"
                placeholder="[zipCode]"
                value={formData.zip_code}
                onChange={handleInputChange}
                onCopy={copyToClipboard}
              />
              <FormField
                label="Complete Mailing Address"
                name="complete_address"
                placeholder="[mailingAddress]"
                value={formData.complete_address}
                onChange={handleInputChange}
                onCopy={copyToClipboard}
              />
            </div>
          </SectionCard>
        )}

        {/* Social Information */}
        {isLoading ? (
          <SectionCard title="Social Information" icon={<SocialInfoIcon />}>
            <div className="space-y-3">
              <div className="h-10 bg-gray-200 rounded animate-pulse"></div>
              <div className="h-10 bg-gray-200 rounded animate-pulse"></div>
              <div className="h-10 bg-gray-200 rounded animate-pulse"></div>
            </div>
          </SectionCard>
        ) : (
          <SectionCard
            title="Social Information"
            icon={<SocialInfoIcon />}
          >
            <div className="space-y-3">
              <FormField
                label="Facebook Page URL"
                name="facebook_url"
                placeholder="[facebookUrl]"
                value={formData.facebook_url}
                onChange={handleInputChange}
                onCopy={copyToClipboard}
              />
              <FormField
                label="LinkedIn Profile URL"
                name="linkedin_url"
                placeholder="[linkedInUrl]"
                value={formData.linkedin_url}
                onChange={handleInputChange}
                onCopy={copyToClipboard}
              />
              <FormField
                label="Twitter URL"
                name="twitter_url"
                placeholder="[twitterUrl]"
                value={formData.twitter_url}
                onChange={handleInputChange}
                onCopy={copyToClipboard}
              />
            </div>
          </SectionCard>
        )}

        {/* Regions Served */}
        <SectionCard
          title="Regions Served"
          icon={<GlobeIcon />}
          maxWidth="max-w-[1150px]"
        >
          <p className="mb-4 text-sm text-[#6F6F7B]">
            Select the regions your business serves. Multi-region legal pages show only the sections for the regions
            you tick here, and update by themselves when you change this later (no page editing). With nothing ticked,
            every section shows.
          </p>
          <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
            {REGION_OPTIONS.map(({ value, label }) => (
              <label
                key={value}
                className="flex cursor-pointer items-center gap-3 rounded-xl border border-[#E4E4E7] p-4 transition hover:border-[#7C3BED]"
              >
                <input
                  type="checkbox"
                  checked={(formData.regions_served || []).includes(value)}
                  onChange={() => handleRegionsChange(value)}
                  className="h-4 w-4 rounded border-gray-300 text-[#7C3BED] focus:ring-[#7C3BED]"
                />
                <span className="text-sm font-medium text-[#17171C]">{label}</span>
              </label>
            ))}
          </div>

          {/* For people writing their own pages; template users don't need this. */}
          <div className="mt-4 rounded-xl border border-[#E4E4E7] bg-[#FAFAFA] px-4 py-3 text-sm text-[#6F6F7B]">
            <p className="!mb-2 font-medium text-[#17171C]">Writing your own legal page?</p>
            <p className="!mb-2">
              Put a paragraph between <code className="text-[#7C3BED]">[lp_if region="eu"]</code> and{' '}
              <code className="text-[#7C3BED]">[/lp_if]</code>, and it only appears on the page while that region is ticked above:
            </p>
            <pre className="!mb-2 whitespace-pre-wrap rounded-lg bg-white px-3 py-2 font-mono text-xs text-[#17171C] ring-1 ring-[#E4E4E7]">
{`[lp_if region="eu"]
Your rights under GDPR: you can access, correct or delete your data.
[/lp_if]`}
            </pre>
            <p className="!mb-0">
              Region names: <code>eu</code>, <code>uk</code>, <code>us</code>, <code>canada</code>, <code>australia</code>.
              For several, separate them with commas: <code>region="canada,australia"</code>.
            </p>
          </div>
        </SectionCard>

        {/* Action Bar */}
        <div className="flex items-center justify-start gap-2 rounded-xl p-4">
          <button
            type="submit"
            disabled={saving}
            className={[
              "inline-flex items-center justify-center rounded-xl px-6 py-[14px] text-sm font-semibold text-white shadow-[0px_4px_14px_-2px_#7C3BED40] transition",
              saving ? "cursor-not-allowed bg-indigo-400" : "bg-[#7C3BED] hover:bg-indigo-700",
            ].join(" ")}
          >
            <img src={save} alt="Save Icon" className="mr-2 h-4 w-4" />
            {saving ? (
              <span className="flex items-center gap-2">
                <SavingIcon />
                Saving...
              </span>
            ) : (
              "Save Changes"
            )}
          </button>

            <button
              type="button"
              onClick={handleResetClick}
              className="inline-flex items-center justify-center rounded-xl border border-[#E4E4E7] bg-white px-6 py-[14px] text-sm font-semibold text-[#17171C] transition hover:bg-gray-50"
            >
              <img src={reset} alt="Reset Icon" className="mr-2 h-4 w-4" />
              Reset Fields
            </button>
            <button
              type="button"
              onClick={handleDeleteClick}
              className="inline-flex items-center justify-center rounded-xl border border-[#E4E4E7] bg-white px-6 py-[14px] text-sm font-semibold text-[#EF4343]"
            >
              <img src={deleteIcon} alt="Reset Data Icon" className="mr-2 h-4 w-4" />
              Reset Saved Data
            </button>
        </div>
      </div>

      <ConfirmationModal
        isOpen={showDeleteModal}
        onClose={() => setShowDeleteModal(false)}
        onConfirm={handleResetSavedData}
        title="Confirm Delete"
        message="This will permanently delete all saved data. Are you sure you want to proceed?"
        confirmText="Delete"
        cancelText="Cancel"
      />
    </form>
  );
};

export default GeneralInformation;