import React, { useState, useRef, useEffect } from 'react';
import TemplateTableRow from './Templatetablerow';
import ProFeaturePopover from '../../../components/common/ProFeaturePopover';
import { usePromo, BoltIcon, PromoButton } from '../../../components/common/BlackFriday';

/** Black Friday 2026 row above the first locked Pro template (remove after the sale). */
const PromoRow = ({ promo, proCount }) => (
  <tr>
    <td colSpan={4} className="py-3">
      <div className="flex flex-col gap-3 rounded-xl bg-[linear-gradient(90deg,#17171C_0%,#2E1065_100%)] px-6 py-3.5 sm:flex-row sm:items-center sm:justify-between">
        <p className="!m-0 flex flex-wrap items-center gap-x-5 gap-y-1 !text-sm !text-[#E4E4E7]">
          <span className="inline-flex items-center gap-2 text-[13px] font-extrabold uppercase tracking-[0.14em] text-[#FCD34D]">
            <BoltIcon /> Black Friday
          </span>
          <span>
            Unlock all <strong className="text-white">{proCount} Pro templates</strong> below for{' '}
            <strong className="text-[#FCD34D]">{promo.off} off</strong>. Ends in {promo.leftText}.
          </span>
        </p>
        <PromoButton promo={promo} className="!py-2">Unlock for {promo.off} off</PromoButton>
      </div>
    </td>
  </tr>
);

const TemplatesTable = ({ templates = [], loading = false, onEdit, onDelete, isProActive, proCount = 0 }) => {
  const promo = usePromo();
  // `popover` is { id, top } — `top` is the open row's bottom edge measured
  // against tableWrapperRef, so the popover can be rendered once (not
  // per-row) and centered on the full row/table width, below that row.
  const [popover, setPopover] = useState(null);
  const tableWrapperRef = useRef(null);

  const handleTogglePopover = (templateId, rowEl) => {
    setPopover((current) => {
      if (current?.id === templateId) return null;

      if (!rowEl || !tableWrapperRef.current) {
        return { id: templateId, top: 0 };
      }

      const wrapperRect = tableWrapperRef.current.getBoundingClientRect();
      const rowRect = rowEl.getBoundingClientRect();
      const top = rowRect.bottom - wrapperRect.top + tableWrapperRef.current.scrollTop + 8;

      return { id: templateId, top };
    });
  };

  const handleClosePopover = () => setPopover(null);

  // Close only when the click lands outside the whole table — clicks on
  // another row are left to that row's own onClick, which already
  // switches `popover` directly. Closing here too would race with that
  // click and force a second click to open the new row's popover.
  useEffect(() => {
    if (popover === null) return;

    const handleOutsideClick = (event) => {
      if (tableWrapperRef.current && !tableWrapperRef.current.contains(event.target)) {
        setPopover(null);
      }
    };

    document.addEventListener('mousedown', handleOutsideClick);
    return () => document.removeEventListener('mousedown', handleOutsideClick);
  }, [popover]);

  const popoverTemplate = popover ? templates.find((t) => t.id === popover.id) : null;
  // During the sale, the promo row goes above the first locked template on this page.
  const promoBeforeId = promo && !isProActive ? templates.find((t) => t.type === 'pro')?.id : null;

  if (loading) {
    return (
      <div className="space-y-3 mt-6">
        {[...Array(10)].map((_, index) => (
          <div
            key={index}
            className="h-14 bg-gray-100 rounded-xl animate-pulse"
          />
        ))}
      </div>
    );
  }

  if (templates.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-16 text-center mt-6">
        <div className="text-7xl mb-6 opacity-70">📝</div>
        <h3 className="text-xl font-semibold text-[#17171C] mb-3">
          No Templates Found
        </h3>
        <p className="text-[#6F6F7B] max-w-md">
          No templates match your search criteria.
        </p>
      </div>
    );
  }

  return (
    // Two levels are needed here, not one: `overflow-x-auto` forces the
    // browser to also compute `overflow-y` as `auto` on the SAME element
    // (a real CSS quirk, not fixable by also setting `overflow-y-visible`
    // — that gets coerced to `auto` too). So the horizontal scroll lives
    // on this inner div around just the `<table>`, while the popover is
    // positioned against the outer, unclipped `relative` wrapper — that's
    // what was cutting the popover off near the bottom of the table.
    <div ref={tableWrapperRef} className="relative bg-white mt-6">
      <div className="overflow-x-auto">
        <table className="w-full min-w-[900px]">
          <thead>
            <tr className="h-12 border border-[#E4E4E7]">
              <th className="text-left py-4 px-6 text-xs font-semibold text-[#6F6F7B] uppercase tracking-wider w-20">
                ID
              </th>
              <th className="text-left py-4 px-6 text-xs font-semibold text-[#6F6F7B] uppercase tracking-wider">
                Template Name
              </th>
              <th className="text-left py-4 px-6 text-xs font-semibold text-[#6F6F7B] uppercase tracking-wider w-32">
                Type
              </th>
              <th className="text-right py-4 px-6 text-xs font-semibold text-[#6F6F7B] uppercase tracking-wider w-32">
                Actions
              </th>
            </tr>
          </thead>
          <tbody className="divide-y divide-[#E4E4E7]">
            {templates.map((template) => (
              <React.Fragment key={template.id}>
              {template.id === promoBeforeId && (
                <PromoRow promo={promo} proCount={proCount} />
              )}
              <TemplateTableRow
                template={template}
                onEdit={onEdit}
                onDelete={onDelete}
                isProActive={isProActive}
                isPopoverOpen={popover?.id === template.id}
                onTogglePopover={(rowEl) => handleTogglePopover(template.id, rowEl)}
              />
              </React.Fragment>
            ))}
          </tbody>
        </table>
      </div>

      {popoverTemplate && (
        <div
          className="absolute left-1/2 z-20 -translate-x-1/2"
          style={{ top: popover.top }}
        >
          <ProFeaturePopover
            ctaLabel={promo ? `Upgrade for ${promo.off} off` : 'Upgrade to Pro'}
            {...(promo ? { ctaHref: promo.url } : {})}
            description={`The "${popoverTemplate.name}" template is available in the Pro version. Upgrade to Pro to unlock this template and more powerful features.`}
            onClose={handleClosePopover}
          />
        </div>
      )}
    </div>
  );
};

export default TemplatesTable;