import React, { useState } from 'react';
import ToggleSwitch from '../../../../../common/Toggleswitch';
import { LockIcon } from '../../../components/common/ProFeatureModal';

const SOURCE_LABELS = {
  plugin: 'Active plugin',
  option: 'WordPress setting',
  cookie: 'Cookie scan',
  scan: 'Cookie scan',
  content: 'Page content',
};

const detectedVia = (service) =>
  service.detected
    ? [...new Set(service.sources.map((source) => SOURCE_LABELS[source] || source))].join(', ')
    : 'Added by you';

const inputCls =
  '!h-[38px] !min-w-[180px] !rounded-xl !border !border-[#E4E4E7] !bg-white !px-3 !pr-8 !text-sm !text-[#17171C] focus:!border-[#7C3BED] focus:!shadow-none';
const smallBtn =
  'inline-flex cursor-pointer items-center justify-center gap-1.5 rounded-xl border border-[#E4E4E7] bg-white px-3 py-2 text-sm font-medium text-[#17171C] transition hover:bg-[#FAFAFA] disabled:cursor-not-allowed disabled:opacity-50';

/**
 * Add a service by hand: sits in the card header, so it's reachable without
 * scrolling past the whole list.
 */
export const AddService = ({ services, locked, busy, onChange }) => {
  const [addId, setAddId] = useState('');
  const addable = services.filter((service) => !service.detected && !(service.shown ?? service.detected));

  if (!addable.length) {
    return null;
  }

  return (
    <div className="flex flex-wrap items-center gap-2">
      <label htmlFor="lp-smart-policy-add" className="screen-reader-text">Add a service manually</label>
      <select id="lp-smart-policy-add" className={inputCls} value={addId} onChange={(e) => setAddId(e.target.value)}>
        <option value="">Add a service…</option>
        {addable.map((service) => (
          <option key={service.id} value={service.id}>{service.name}</option>
        ))}
      </select>
      <button
        type="button"
        className={smallBtn}
        disabled={!addId || busy}
        onClick={() => {
          onChange(addId, true);
          setAddId('');
        }}
      >
        {locked && <LockIcon />}
        Add
      </button>
    </div>
  );
};

/**
 * Detected services get a toggle: switching one off keeps it out of the policy,
 * and Re-check can't bring it back. Services added by hand get Remove instead,
 * because "off" for those simply means gone. `locked`: both stay visible, and
 * `onChange` shows why they can't be used.
 */
const ServiceRow = ({ service, locked, busy, onChange }) => {
  const shown = service.shown ?? service.detected;

  return (
    <li className="flex items-center justify-between gap-3 py-2.5">
      <div className="min-w-0">
        <div className={`truncate text-sm font-medium ${shown ? 'text-[#17171C]' : 'text-[#A1A1AA] line-through'}`}>{service.name}</div>
        <div className="text-xs text-[#6F6F7B]">{detectedVia(service)}</div>
      </div>
      <div className="flex shrink-0 items-center gap-2">
        {locked && <span className="text-[#6F6F7B]"><LockIcon /></span>}
        {service.detected ? (
          <ToggleSwitch
            checked={shown}
            label={`Include ${service.name} in the policy`}
            onChange={(value) => onChange(service.id, value)}
          />
        ) : (
          <button
            type="button"
            disabled={busy}
            onClick={() => onChange(service.id, false)}
            aria-label={`Remove ${service.name}`}
            className="cursor-pointer rounded-lg border-0 bg-transparent px-2 py-1 text-xs font-medium text-[#DC2626] transition hover:bg-red-50 disabled:cursor-not-allowed disabled:opacity-50"
          >
            Remove
          </button>
        )}
      </div>
    </li>
  );
};

const ServiceTable = ({ services, categories, locked, busy, onChange }) => {
  const rows = services.filter((service) => service.detected || service.shown);

  if (!rows.length) {
    return <p className="!text-sm !text-[#6F6F7B]">No services found yet. Use Re-check now after adding a plugin or embed.</p>;
  }

  // Category order comes from the server; services are already in that order.
  const groups = Object.keys(categories)
    .map((id) => ({ id, label: categories[id], items: rows.filter((service) => service.category === id) }))
    .filter((group) => group.items.length);

  return (
    <div className="gap-x-10 lg:columns-2">
      {groups.map((group) => (
        <section key={group.id} className="mb-4 break-inside-avoid">
          <h4 className="!mb-0 !mt-0 border-b border-[#F4F4F5] pb-1.5 !text-xs !font-semibold uppercase tracking-wide !text-[#6F6F7B]">
            {group.label}
          </h4>
          <ul className="!m-0 divide-y divide-[#F4F4F5]">
            {group.items.map((service) => (
              <ServiceRow key={service.id} service={service} locked={locked} busy={busy} onChange={onChange} />
            ))}
          </ul>
        </section>
      ))}
    </div>
  );
};

export default ServiceTable;
