import React, { useState, useEffect } from 'react';
import { Toast } from '../../../../components/common/Toast';
import SectionCard from '../../../../components/common/SectionCard';
import ToggleField from '../../../../components/common/ToggleField';
import InputField from '../../../../components/common/InputField';
import { ColorPaletteIcon, CookieComplianceIcon, CustomizationIcon } from '../../../../components/common/SvgIcon';
import PositionPreview from '../PositionPreview';
import ColorField from '../ColorField';
import Skeleton from '../../../../components/common/Skeleton';
import { LockIcon } from '../../../../components/common/ProFeatureModal';

const save = `${LEGAL_PAGES.assets_url}/images/icons/save.png`;

const POSITIONS = [
  { value: 'bottom',       label: 'Bottom Bar',    bars: [{ pos: 'bottom', full: true }] },
  { value: 'bottom-left',  label: 'Bottom Left',   bars: [{ pos: 'bottom', full: false, align: 'left' }] },
  { value: 'bottom-right', label: 'Bottom Right',  bars: [{ pos: 'bottom', full: false, align: 'right' }] },
  { value: 'top',          label: 'Top Bar',       bars: [{ pos: 'top', full: true }] },
  { value: 'top-left',     label: 'Top Left',      bars: [{ pos: 'top', full: false, align: 'left' }] },
  { value: 'top-right',    label: 'Top Right',     bars: [{ pos: 'top', full: false, align: 'right' }] },
];

const CATEGORIES = [
  { value: 'functional',  label: 'Functional',  description: 'Needed for the site to work, e.g. login and consent choices.', locked: true },
  { value: 'preferences', label: 'Preferences', description: 'Remember choices such as language or region.' },
  { value: 'statistics',  label: 'Statistics',  description: 'Analytics that show how visitors use the site.' },
  { value: 'marketing',   label: 'Marketing',   description: 'Ads and tracking across websites.' },
];

const ProTitle = ({ title, locked }) => (
  <span className="inline-flex items-center gap-2">
    {title}
    {locked && (
      <span className="inline-flex items-center gap-1 rounded-full bg-[#7C3BED1A] px-2 py-0.5 text-[11px] font-semibold text-[#7C3BED]">
        <LockIcon className="h-3 w-3" /> Pro
      </span>
    )}
  </span>
);

/**
 * Without `locked` renders children as-is. With it, shows them dimmed and
 * inert (showing the defaults) under a click catcher that opens the Pro modal
 * for `feature`.
 */
const ProArea = ({ locked, onLocked, feature = 'customize', children }) => {
  if (!locked) {
    return children;
  }
  return (
    <div className="relative">
      <div aria-hidden="true" className="pointer-events-none select-none opacity-60">
        {children}
      </div>
      <button
        type="button"
        aria-label="Pro feature"
        className="absolute inset-0 z-10 cursor-pointer bg-transparent"
        onClick={() => onLocked(feature)}
      />
    </div>
  );
};

/**
 * The consent banner is a Legal Pages Pro feature. `locked` (no Pro, or no valid
 * license): every section shows the defaults dimmed and opens the Pro modal, and
 * there is nothing to save.
 */
const GCookieSettings =({ isLoading, setIsLoading, locked = false, onLocked = () => {} }) => {
  const [saving, setSaving] = useState(false);
  const [formData, setFormData] = useState({
    show_cookie_warning: false,
    auto_reload: false,
    cookie_display_position: 'bottom',
    cookie_policy_link: '',
    learn_more_link_text: '',
    cookie_message: '',
    cookie_dismiss_button: '',
    cookie_deny_button: '',
    cookie_accept_button: '',
    cookie_message_bg: '#1f2937',
    cookie_message_color: '#ffffff',
    cookie_button_bg: '#7c3aed',
    cookie_button_text_color: '#ffffff',
    cookie_title: '',
    cookie_preferences_button: '',
    cookie_save_button: '',
    cookie_manage_button: '',
    cookie_categories: ['preferences', 'statistics', 'marketing'],
    show_manage_button: true,
    google_consent_mode: false,
  });

  const toggleCategory = (value) =>
    setFormData(prev => ({
      ...prev,
      cookie_categories: prev.cookie_categories.includes(value)
        ? prev.cookie_categories.filter(c => c !== value)
        : [...prev.cookie_categories, value],
    }));

  useEffect(() => {
    fetchSettings();
  }, []);

  const fetchSettings = async () => {
    setIsLoading(true);
    try {
      const response = await fetch(`${LEGAL_PAGES.apiUrl}/cookie-settings`, {
        headers: { 'X-WP-Nonce': LEGAL_PAGES.nonce },
      });
      const result = await response.json();
      if (result.success && result.data) {
        setFormData(prev => ({ ...prev, ...result.data }));
      }
    } catch (e) {
      Toast.error('Failed to load cookie settings');
    } finally {
      setIsLoading(false);
    }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSaving(true);
    try {
      const response = await fetch(`${LEGAL_PAGES.apiUrl}/cookie-settings`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-WP-Nonce': LEGAL_PAGES.nonce,
        },
        body: JSON.stringify(formData),
      });
      const result = await response.json();
      if (result.success) {
        Toast.success('Cookie settings saved successfully!');
        if (result.data) setFormData(prev => ({ ...prev, ...result.data }));
      } else {
        Toast.error('Failed to save cookie settings.');
      }
    } catch (e) {
      Toast.error('An error occurred while saving.');
    } finally {
      setSaving(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} noValidate>
      <div className="space-y-6">

        {/* EU Cookie Compliance */}
        <SectionCard
          title={<ProTitle title="EU Cookie Compliance" locked={locked} />}
          maxHeight=""
          icon={
            <CookieComplianceIcon />
          }
        >
          {isLoading ? <Skeleton /> : (
            <div className="space-y-6">
              <ProArea locked={locked} onLocked={onLocked} feature="banner">
              <div className="space-y-6">
              <div className='bg-[#F4F4F580] p-2 rounded-xl'>
                <ToggleField
                  label="Show EU Cookie Alert"
                  description="Display cookie consent notification to users"
                  name="show_cookie_warning"
                  checked={formData.show_cookie_warning}
                  onChange={(name, value) => setFormData(prev => ({ ...prev, [name]: value }))}
                />
              </div>
              <div className='bg-[#F4F4F580] p-2 rounded-xl'>
                <ToggleField
                  label="Auto-reload After Consent"
                  description="Reload the page after user accepts cookie"
                  name="auto_reload"
                  checked={formData.auto_reload}
                  onChange={(name, value) => setFormData(prev => ({ ...prev, [name]: value }))}
                />
              </div>
              <div className='bg-[#F4F4F580] p-2 rounded-xl'>
                <ToggleField
                  label="Show Manage Consent Button"
                  description="Floating button that lets visitors change their choice later. You can also use the [lp_manage_consent] shortcode."
                  name="show_manage_button"
                  checked={formData.show_manage_button}
                  onChange={(name, value) => setFormData(prev => ({ ...prev, [name]: value }))}
                />
              </div>
              <div className='bg-[#F4F4F580] p-2 rounded-xl'>
                <ToggleField
                  label="Google Consent Mode v2"
                  description="Tell Google tags (Analytics, Ads, Tag Manager) which categories the visitor accepted"
                  name="google_consent_mode"
                  checked={formData.google_consent_mode}
                  onChange={(name, value) => setFormData(prev => ({ ...prev, [name]: value }))}
                />
              </div>
              </div>
              </ProArea>

              {/* Position picker */}
              <ProArea locked={locked} onLocked={onLocked}>
              <div>
                <label className="block text-sm font-medium text-[#17171C] mb-3">
                  <ProTitle title="Cookie Bar Position" locked={locked} />
                </label>
                <div className="grid grid-cols-3 gap-3">
                  {POSITIONS.map(pos => (
                    <PositionPreview
                      key={pos.value}
                      config={pos}
                      selected={formData.cookie_display_position}
                      onSelect={(val) => setFormData(prev => ({ ...prev, cookie_display_position: val }))}
                    />
                  ))}
                </div>
              </div>
              </ProArea>
            </div>
          )}
        </SectionCard>

        {/* Consent Categories */}
        <SectionCard
          title={<ProTitle title="Consent Categories" locked={locked} />}
          maxHeight=""
          icon={<CookieComplianceIcon />}
        >
          {isLoading ? <Skeleton /> : (
            <ProArea locked={locked} onLocked={onLocked}>
            <div className="space-y-3">
              <p className="!text-sm !text-[#6F6F7B]">
                Categories visitors can switch on in "View preferences". Blocked services only load once their
                category is accepted — set each service's category under Block Services → Available Services.
              </p>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                {CATEGORIES.map(cat => (
                  <label
                    key={cat.value}
                    className={`flex items-start gap-3 rounded-xl border border-[#E4E4E7] p-3 ${cat.locked ? 'bg-[#F4F4F580]' : 'cursor-pointer hover:border-[#7C3BED]'}`}
                  >
                    <input
                      type="checkbox"
                      className="!mt-1"
                      checked={cat.locked || formData.cookie_categories.includes(cat.value)}
                      disabled={cat.locked}
                      onChange={() => toggleCategory(cat.value)}
                    />
                    <span>
                      <span className="block text-sm font-medium text-[#17171C]">
                        {cat.label}{cat.locked && <span className="ml-2 text-xs font-normal text-[#6F6F7B]">Always active</span>}
                      </span>
                      <span className="block text-xs text-[#6F6F7B]">{cat.description}</span>
                    </span>
                  </label>
                ))}
              </div>
            </div>
            </ProArea>
          )}
        </SectionCard>

        {/* Customization */}
        <SectionCard
          title={<ProTitle title="Customization" locked={locked} />}
          maxHeight=""
          icon={<CustomizationIcon />}
        >
          {isLoading ? <Skeleton /> : (
            <ProArea locked={locked} onLocked={onLocked}>
            <div className="space-y-4">
              <InputField
                label="Banner Title"
                name="cookie_title"
                value={formData.cookie_title}
                onChange={handleInputChange}
                placeholder="Manage Consent"
              />
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <InputField
                  label="Cookie Policy Link"
                  name="cookie_policy_link"
                  value={formData.cookie_policy_link}
                  onChange={handleInputChange}
                  placeholder="https://www.cookiesandyou.com/"
                />
                <InputField
                  label="Learn More Link Text"
                  name="learn_more_link_text"
                  value={formData.learn_more_link_text}
                  onChange={handleInputChange}
                  placeholder="Learn more"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-[#17171C] mb-1.5">Cookie Message</label>
                <textarea
                  name="cookie_message"
                  value={formData.cookie_message}
                  onChange={handleInputChange}
                  rows={3}
                  placeholder="This website uses cookies to ensure you get the best experience on our website."
                  className="h-[80px] w-full !rounded-xl border !border-[#E4E4E7] px-4 text-sm text-[#17171C] focus:!border-[#17171C] focus:!shadow-none focus:!ring-0 outline-none"
                />
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {/* <InputField
                  label="Dismiss Button Text"
                  name="cookie_dismiss_button"
                  value={formData.cookie_dismiss_button}
                  onChange={handleInputChange}
                  placeholder="Dismiss"
                /> */}
                <InputField
                  label="Deny Button Text"
                  name="cookie_deny_button"
                  value={formData.cookie_deny_button}
                  onChange={handleInputChange}
                  placeholder="Deny"
                />
                <InputField
                  label="Accept Button Text"
                  name="cookie_accept_button"
                  value={formData.cookie_accept_button}
                  onChange={handleInputChange}
                  placeholder="Accept"
                />
                <InputField
                  label="View Preferences Button Text"
                  name="cookie_preferences_button"
                  value={formData.cookie_preferences_button}
                  onChange={handleInputChange}
                  placeholder="View preferences"
                />
                <InputField
                  label="Save Preferences Button Text"
                  name="cookie_save_button"
                  value={formData.cookie_save_button}
                  onChange={handleInputChange}
                  placeholder="Save preferences"
                />
                <InputField
                  label="Manage Consent Button Text"
                  name="cookie_manage_button"
                  value={formData.cookie_manage_button}
                  onChange={handleInputChange}
                  placeholder="Manage consent"
                />
              </div>
            </div>
            </ProArea>
          )}
        </SectionCard>

        {/* Colors */}
        <SectionCard
          title={<ProTitle title="Colors" locked={locked} />}
          icon={<ColorPaletteIcon />}
        >
          {isLoading ? <Skeleton /> : (
            <ProArea locked={locked} onLocked={onLocked}>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <ColorField
                label="Banner Background"
                name="cookie_message_bg"
                value={formData.cookie_message_bg}
                onChange={handleInputChange}
              />
              <ColorField
                label="Banner Text Color"
                name="cookie_message_color"
                value={formData.cookie_message_color}
                onChange={handleInputChange}
              />
              <ColorField
                label="Button Background"
                name="cookie_button_bg"
                value={formData.cookie_button_bg}
                onChange={handleInputChange}
              />
              <ColorField
                label="Button Text Color"
                name="cookie_button_text_color"
                value={formData.cookie_button_text_color}
                onChange={handleInputChange}
              />
            </div>
            </ProArea>
          )}
        </SectionCard>

        {/* Save */}
        {!locked && (
        <div className="flex items-center justify-start gap-2 rounded-xl p-4">
          <button
            type="submit"
            disabled={saving}
            className={[
              'inline-flex items-center cursor-pointer justify-center rounded-xl px-6 py-[14px] text-sm font-semibold text-white shadow-[0px_4px_14px_-2px_#7C3BED40] transition',
              saving ? 'cursor-not-allowed bg-indigo-400' : 'bg-[#7C3BED] hover:bg-indigo-700',
            ].join(' ')}
          >
            <img src={save} alt="Save" className="mr-2 h-4 w-4" />
            {saving ? 'Saving...' : 'Save Settings'}
          </button>
        </div>
        )}
      </div>
    </form>
  );
};

export default GCookieSettings;