import React from 'react';
import SectionCard from '../../../components/common/SectionCard';
import { PopupConfigurationcon } from '../../../components/common/SvgIcon';
import ToggleField from '../../../components/common/ToggleField';
import InputField from '../../../components/common/InputField';

const noop = () => {};

/**
 * Static, non-fetching mockup of the Popup Configuration form.
 * Used only as the blurred backdrop behind ProFeatureLock when Pro isn't
 * active — deliberately does NOT call the /popup-settings REST endpoint
 * or reuse the live PopupSettings component, so a locked user never sees
 * its loading-skeleton flash or their own (faded) real saved values.
 */
const PopupSettingsPreview = () => (
  <SectionCard maxHeight="max-h-[736px]" title="Popup Configuration" icon={<PopupConfigurationcon />}>
    <div className="space-y-6">
      <ToggleField
        label="Disable Popup Notice Title"
        description="Hide the popup title"
        name="disable_popup_title"
        checked={false}
        onChange={noop}
      />

      <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
        <InputField label="Popup Notice Title" name="popup_notice_title" value="" onChange={noop} />
        <InputField label="Agreement Text" name="agreement_text" value="" onChange={noop} />
        <InputField label="Accept Button Text" name="accept_button_text" value="" onChange={noop} />
        <InputField type="number" label="Popup Width (px)" name="popup_width" value="" onChange={noop} />
        <InputField type="number" label="Popup Height (px)" name="popup_height" value="" onChange={noop} />
      </div>

      <ToggleField
        label="Stop Showing Popup Once Accepted"
        description="Prevent popup from showing again if accepted"
        name="stop_showing_popup"
        checked={false}
        onChange={noop}
      />

      <ToggleField
        label="Disable Popup JS & CSS"
        description="Disable if your theme already has Bootstrap"
        name="disable_popup_js_css"
        checked={false}
        onChange={noop}
      />
    </div>
  </SectionCard>
);

export default PopupSettingsPreview;
