import React, { useState, useEffect, useCallback } from 'react';
import MainPageLayout from '../../components/common/MainPageLayout';
import SectionCard from '../../components/common/SectionCard';
import Skeleton from '../../components/common/Skeleton';
import SmartPolicyNotice from '../../components/common/SmartPolicyNotice';
import ProFeatureModal from '../../components/common/ProFeatureModal';
import { Toast } from '../../components/common/Toast';
import { GeneralInformationIcon } from '../../components/common/SvgIcon';
import LockBanner from './components/LockBanner';
import ServiceTable, { AddService } from './components/ServiceTable';

const SHORTCODE = '[lp_smart_policy]';

const primaryBtn =
  'inline-flex cursor-pointer items-center justify-center rounded-xl bg-[#7C3BED] px-6 py-[11px] text-sm font-semibold text-white shadow-[0px_4px_14px_-2px_#7C3BED40] transition hover:bg-indigo-700 disabled:cursor-not-allowed disabled:bg-indigo-400';
const secondaryBtn =
  'inline-flex cursor-pointer items-center justify-center rounded-xl border border-[#E4E4E7] bg-white px-3.5 py-[11px] text-sm font-medium text-[#17171C] transition hover:bg-[#FAFAFA] disabled:cursor-not-allowed disabled:opacity-50';

const api = async (path, { method = 'GET', body } = {}) => {
  const res = await fetch(`${LEGAL_PAGES.apiUrl}${path}`, {
    method,
    headers: {
      'X-WP-Nonce': LEGAL_PAGES.nonce,
      ...(body ? { 'Content-Type': 'application/json' } : {}),
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  const json = await res.json();
  if (!res.ok) {
    throw new Error(json?.message || `Request failed (${res.status})`);
  }
  return json.data;
};

// navigator.clipboard is missing on http:// sites.
const copyText = (text) => {
  if (navigator.clipboard?.writeText) {
    return navigator.clipboard.writeText(text);
  }
  const area = document.createElement('textarea');
  area.value = text;
  area.style.position = 'fixed';
  area.style.left = '-999999px';
  document.body.appendChild(area);
  area.select();
  const copied = document.execCommand('copy');
  document.body.removeChild(area);
  return copied ? Promise.resolve() : Promise.reject(new Error('Copy failed'));
};

const editUrl = (id) => `${LEGAL_PAGES.admin_url}post.php?post=${id}&action=edit`;

const PageList = ({ pages }) => pages.map((page, index) => (
  <span key={page.id}>
    {index > 0 && ', '}
    <a href={editUrl(page.id)} className="text-[#7C3BED]">{page.title || `#${page.id}`}</a>
  </span>
));

const Warning = ({ children }) => (
  <p className="!mt-4 rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 !text-sm !text-[#17171C]">{children}</p>
);

/**
 * Finding 13 in docs/smart-policy-plan.md: existing pages don't gain the tag, so
 * this says plainly whether the list reaches a page people can read.
 */
const PageState = ({ pages }) => {
  const published = pages.filter((page) => page.status === 'publish');

  if (published.length) {
    return <p className="!mt-4 !text-sm !text-[#6F6F7B]">Showing on: <PageList pages={published} /></p>;
  }
  if (pages.length) {
    return <Warning>The shortcode is only on a draft (<PageList pages={pages} />). Visitors won't see these services until it's published.</Warning>;
  }
  return <Warning>Not on any page yet. Add the shortcode to your privacy policy page so these services appear in it.</Warning>;
};

const ScanHint = () => (
  <Warning>
    Google Analytics, Meta Pixel and Google Ads are found by a cookie scan.{' '}
    <a href={LEGAL_PAGES?.cookie_pro ? '#/cookie-bar' : '#/pro-features/cookie-bar'} className="text-[#7C3BED]">Run a cookie scan</a>{' '}
    to include them.
  </Warning>
);

const SmartPolicy = () => {
  const [data, setData] = useState(null);
  const [failed, setFailed] = useState(false);
  const [checking, setChecking] = useState(false);
  const [busy, setBusy] = useState(false);
  const [proModal, setProModal] = useState(false);

  const show = useCallback((overview) => {
    setData(overview);
    LEGAL_PAGES.smart_policy_notice = overview.notice || null;
  }, []);

  useEffect(() => {
    api('/smart-policy').then(show).catch(() => setFailed(true));
  }, [show]);

  const recheck = async () => {
    setChecking(true);
    try {
      show(await api('/smart-policy/recheck', { method: 'POST' }));
      Toast.success('Check finished.');
    } catch (e) {
      Toast.error(e.message || 'The check failed.');
    } finally {
      setChecking(false);
    }
  };

  const saveShown = async (id, shown) => {
    if (busy) {
      return;
    }
    if (data.lock === 'upgrade') {
      setProModal(true);
      return;
    }
    if (data.lock) {
      Toast.info(data.lock === 'license' ? 'Activate your license to change this.' : 'Update Legal Pages Pro to change this.');
      return;
    }
    setBusy(true);
    try {
      show(await api('/smart-policy/overrides', { method: 'POST', body: { id, shown } }));
    } catch (e) {
      Toast.error(e.message || 'Could not save that change.');
    } finally {
      setBusy(false);
    }
  };

  const copyShortcode = () => {
    copyText(SHORTCODE).then(() => Toast.success('Shortcode copied!')).catch(() => Toast.error('Failed to copy'));
  };

  const layout = (children) => (
    <MainPageLayout
      title="Smart Policy"
      description="See which third-party services your site uses and keep your privacy policy in step with them"
    >
      {children}
    </MainPageLayout>
  );

  if (failed) {
    return layout(<p className="!text-sm !text-[#6F6F7B]">Smart Policy couldn't load. Refresh the page to try again.</p>);
  }
  if (!data) {
    return layout(<Skeleton />);
  }

  const locked = Boolean(data.lock);
  const count = data.detected_count;
  // With Pro active the policy prints these services, licensed or not.
  const proActive = data.lock !== 'upgrade' && data.lock !== 'update';

  return layout(
    <>
      {locked && <LockBanner lock={data.lock} count={count} updateUrl={data.pro_update_url} />}
      <SmartPolicyNotice notice={data.notice} wrapperClassName="mb-6" showLink={false} key={(data.notice?.services || []).join()} />

      <div className="space-y-6">
        <SectionCard title={`We found ${count} ${count === 1 ? 'service' : 'services'} on your site`} icon={<GeneralInformationIcon />} maxHeight="">
          <div className="flex flex-wrap items-center justify-between gap-4">
            <p className="!m-0 !text-sm !text-[#6F6F7B]">
              Last checked: {data.last_checked ? new Date(data.last_checked * 1000).toLocaleString() : 'Never'}
            </p>
            <button type="button" className={primaryBtn} onClick={recheck} disabled={checking}>
              {checking ? 'Checking...' : 'Re-check now'}
            </button>
          </div>

          {proActive && (
            <>
              <div className="mt-4 flex flex-wrap items-center gap-3 border-t border-[#F4F4F5] pt-4">
                <code className="rounded-lg bg-[#F4F4F5] px-3 py-2 text-sm text-[#17171C]">{SHORTCODE}</code>
                <button type="button" className={secondaryBtn} onClick={copyShortcode}>Copy</button>
              </div>
              <PageState pages={data.pages} />
            </>
          )}

          {!data.has_scan && !LEGAL_PAGES?.cookie_legacy_pro && <ScanHint />}
        </SectionCard>

        <SectionCard title="Services in your policy" icon={<GeneralInformationIcon />} maxHeight="">
          <div className="-mt-2 mb-4 flex flex-wrap items-center justify-between gap-3">
            <p className="!m-0 !text-sm !text-[#6F6F7B]">
              Switch off a detected service to leave it out. Services you add stay until you remove them.
            </p>
            <AddService services={data.services} locked={locked} busy={busy} onChange={saveShown} />
          </div>
          <ServiceTable
            services={data.services}
            categories={data.categories}
            locked={locked}
            busy={busy}
            onChange={saveShown}
          />
        </SectionCard>
      </div>

      <ProFeatureModal
        isOpen={proModal}
        onClose={() => setProModal(false)}
        description="Choosing which services appear in your privacy policy is available in Legal Pages Pro."
      />
    </>
  );
};

export default SmartPolicy;
