import React, { useState, useEffect } from 'react';

// Small, dependency-free guided tour: dims the page, draws a highlight ring
// around the current step's target ref, and shows a tooltip with Next/Skip.
const GuidedTour = ({ steps, onFinish }) => {
  const [stepIndex, setStepIndex] = useState(0);
  const [rect, setRect] = useState(null);

  const step = steps[stepIndex];

  useEffect(() => {
    const updateRect = () => {
      const node = step?.target?.current;
      if (node) {
        setRect(node.getBoundingClientRect());
      }
    };

    updateRect();
    window.addEventListener('resize', updateRect);
    window.addEventListener('scroll', updateRect, true);

    return () => {
      window.removeEventListener('resize', updateRect);
      window.removeEventListener('scroll', updateRect, true);
    };
  }, [stepIndex, step]);

  if (!step || !rect) return null;

  const isLast = stepIndex === steps.length - 1;

  // Estimated tooltip footprint — placed below the target by default, flipped
  // above it when there isn't room, and always clamped inside the viewport
  // so it never overlaps the bottom-right toast notifications.
  const TOOLTIP_WIDTH = 320;
  const TOOLTIP_HEIGHT = 150;
  const MARGIN = 16;

  const fitsBelow = rect.bottom + MARGIN + TOOLTIP_HEIGHT <= window.innerHeight;
  const tooltipTop = fitsBelow
    ? rect.bottom + 12
    : Math.max(MARGIN, rect.top - TOOLTIP_HEIGHT - 12);

  const tooltipLeft = Math.min(
    Math.max(MARGIN, rect.left),
    window.innerWidth - TOOLTIP_WIDTH - MARGIN
  );

  return (
    <>
      <div className="fixed inset-0 z-[999997] bg-black/25" style={{ pointerEvents: 'none' }} />

      <div
        className="fixed z-[999998] rounded-xl ring-2 ring-[#7C3BED] ring-offset-2 transition-all duration-200"
        style={{
          top: rect.top - 4,
          left: rect.left - 4,
          width: rect.width + 8,
          height: rect.height + 8,
          pointerEvents: 'none',
        }}
      />

      <div
        className="fixed z-[999999] w-80 rounded-xl bg-white p-4 shadow-xl ring-1 ring-[#E4E4E7]"
        style={{ top: tooltipTop, left: tooltipLeft }}
      >
        <div className="text-sm font-semibold text-[#17171C]">{step.title}</div>
        <p className="mt-1 text-sm text-[#6F6F7B]">{step.body}</p>

        <div className="mt-4 flex items-center justify-between">
          <button
            type="button"
            onClick={onFinish}
            className="text-xs !font-bold text-[#6F6F7B] hover:text-[#17171C]"
          >
            Skip tour
          </button>

          <div className="flex items-center gap-2">
            <span className="text-xs text-[#6F6F7B]">
              {stepIndex + 1}/{steps.length}
            </span>
            <button
              type="button"
              onClick={() => (isLast ? onFinish() : setStepIndex((i) => i + 1))}
              className="rounded-lg bg-[#7C3BED] px-3 py-1.5 text-xs !font-bold text-white hover:bg-indigo-700"
            >
              {isLast ? 'Got it' : 'Next'}
            </button>
          </div>
        </div>
      </div>
    </>
  );
};

export default GuidedTour;
