import React, { useState, useEffect } from 'react';

import { Toast } from '../../../components/common/Toast';
import SectionCard from '../../../components/common/SectionCard';
import FormField from '../../../components/common/FormField';
import { BusinessInformationIcon, ArrowRightIcon, GlobeIcon, SaveButtonIcon } from '../../../components/common/SvgIcon';

// Only these fields are shown to the user in this step; the rest of the
// settings object (address/social) is fetched and carried through untouched
// so saving here never wipes data already entered elsewhere.
const VISIBLE_FIELDS = [
  { name: 'site_url', label: 'Your Site URL', placeholder: '[siteUrl]' },
  { name: 'site_name', label: 'Site / Business Name', placeholder: '[siteName]' },
  { name: 'business_niche', label: 'Business Niche', placeholder: '[businessNiche]' },
  { name: 'phone_number', label: 'Phone Number', placeholder: '[phoneNumber]', type: 'tel' },
  { name: 'email_address', label: 'Email Address', placeholder: '[emailAddress]' },
];

const REGION_OPTIONS = [
  { value: 'eu', label: 'European Union (EU / EEA)' },
  { value: 'uk', label: 'United Kingdom' },
  { value: 'us', label: 'United States' },
  { value: 'canada', label: 'Canada' },
  { value: 'australia', label: 'Australia' },
];

const StepBusinessInfo = ({ onNext, onSkip, skipping = false }) => {
  const [formData, setFormData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    fetchSettings();
  }, []);

  const fetchSettings = async () => {
    setLoading(true);
    try {
      const response = await fetch(`${LEGAL_PAGES.apiUrl}/settings`, {
        headers: {
          'X-WP-Nonce': LEGAL_PAGES.nonce,
        },
      });

      const result = await response.json();

      if (result.success && result.data) {
        setFormData(result.data);
      }
    } catch (error) {
      console.error('Error fetching settings:', error);
      Toast.error('Failed to load business information');
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleRegionsChange = (region) => {
    setFormData((prev) => {
      const current = Array.isArray(prev.regions_served) ? prev.regions_served : [];
      const next = current.includes(region)
        ? current.filter((r) => r !== region)
        : [...current, region];
      return { ...prev, regions_served: next };
    });
  };

  const copyToClipboard = (text) => {
    if (!text) return;
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard
        .writeText(text)
        .then(() => Toast.success('Placeholder copied to clipboard!'))
        .catch(() => Toast.error('Failed to copy to clipboard'));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (formData.email_address && formData.email_address.trim() !== '') {
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(formData.email_address)) {
        Toast.error('Please provide a valid email address');
        return;
      }
    }

    setSaving(true);
    try {
      const response = await fetch(`${LEGAL_PAGES.apiUrl}/settings`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-WP-Nonce': LEGAL_PAGES.nonce,
        },
        body: JSON.stringify(formData),
      });

      const result = await response.json();

      if (result.success) {
        Toast.success('Business information saved!');
        onNext();
      } else {
        Toast.error('Failed to save business information.');
      }
    } catch (error) {
      console.error('Error saving settings:', error);
      Toast.error('An error occurred while saving.');
    } finally {
      setSaving(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} noValidate>
      {loading || !formData ? (
        <SectionCard title="Business Information" icon={<BusinessInformationIcon />} maxWidth="max-w-[1150px]">
          <div className="space-y-3">
            {VISIBLE_FIELDS.map((field) => (
              <div key={field.name} className="h-10 bg-gray-200 rounded animate-pulse"></div>
            ))}
          </div>
        </SectionCard>
      ) : (
        <SectionCard
          title="Business Information"
          icon={<BusinessInformationIcon />}
          maxWidth="max-w-[1150px]"
          maxHeight="max-h-[540px]"
        >
          <div className="space-y-3">
            {VISIBLE_FIELDS.map((field) => (
              <FormField
                key={field.name}
                label={field.label}
                name={field.name}
                placeholder={field.placeholder}
                value={formData[field.name] || ''}
                onChange={handleInputChange}
                onCopy={copyToClipboard}
                type={field.type || 'text'}
              />
            ))}
          </div>
        </SectionCard>
      )}

      {!loading && formData && (
        <div className="mt-6">
          <SectionCard title="Regions Served" icon={<GlobeIcon />} maxWidth="max-w-[1150px]">
            <p className="mb-4 text-sm text-[#6F6F7B]">
              Select the regions your business serves. Multi-region legal pages show only the sections for the regions
              you tick here, and update by themselves if you change this later in Settings. With nothing ticked, every
              section shows.
            </p>
            <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
              {REGION_OPTIONS.map(({ value, label }) => (
                <label
                  key={value}
                  className="flex cursor-pointer items-center gap-3 rounded-xl border border-[#E4E4E7] p-4 transition hover:border-[#7C3BED]"
                >
                  <input
                    type="checkbox"
                    checked={(formData.regions_served || []).includes(value)}
                    onChange={() => handleRegionsChange(value)}
                    className="h-4 w-4 rounded border-gray-300 text-[#7C3BED] focus:ring-[#7C3BED]"
                  />
                  <span className="text-sm font-medium text-[#17171C]">{label}</span>
                </label>
              ))}
            </div>
          </SectionCard>
        </div>
      )}

      <div className="mt-6 flex items-center justify-between gap-3">
        <button
          type="button"
          onClick={onSkip}
          disabled={saving || skipping}
          className="cursor-pointer rounded-xl border border-[#E4E4E7] bg-white px-6 py-[14px] text-sm !font-bold text-[#6F6F7B] transition-all hover:border-[#17171C] hover:text-[#17171C] disabled:cursor-not-allowed disabled:opacity-50"
        >
          {skipping ? 'Skipping...' : "I'll set up later"}
        </button>
        <button
          type="submit"
          disabled={saving || loading || skipping || !formData}
          className={[
            'inline-flex items-center justify-center gap-2 rounded-xl px-8 py-[14px] text-sm !font-bold text-white shadow-[0px_4px_14px_-2px_#7C3BED40] transition',
            saving || loading ? 'cursor-not-allowed bg-indigo-400' : 'bg-[#7C3BED] hover:bg-indigo-700',
          ].join(' ')}
        >
          {saving ? (
            <>
              <SaveButtonIcon />
              Saving...
            </>
          ) : (
            <>
              Next: Create a Legal Page
              <ArrowRightIcon />
            </>
          )}
        </button>
      </div>
    </form>
  );
};

export default StepBusinessInfo;
