import React, { useState, useEffect, useRef } from 'react';
import { Toast } from '../../../../components/common/Toast';
import ConfirmationModal from '../../../../components/common/ConfirmationModal';
import Skeleton from '../../../../components/common/Skeleton';
import SectionCard from '../../../../components/common/SectionCard';
import ScanPanel, { ScanIcon } from './ScanPanel';

// Max time to wait for a scanned page's collector to report before moving on.
const PAGE_TIMEOUT_MS = 20000;

const api = async (path, { method = 'GET', body } = {}) => {
  const res = await fetch(`${LEGAL_PAGES.apiUrl}${path}`, {
    method,
    headers: {
      'X-WP-Nonce': LEGAL_PAGES.nonce,
      ...(body ? { 'Content-Type': 'application/json' } : {}),
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  const json = await res.json();
  if (!res.ok) {
    throw new Error(json?.message || `Request failed (${res.status})`);
  }
  return json;
};

const CookieScanner = ({ locked = false, onLocked = () => {} }) => {
  const [loading, setLoading] = useState(true);
  const [state, setState] = useState({});
  const [cookies, setCookies] = useState([]);
  const [postTypes, setPostTypes] = useState([]);
  const [selectedTypes, setSelectedTypes] = useState([]);
  const [scanning, setScanning] = useState(false);
  const [syncing, setSyncing] = useState(false);
  const [confirmClear, setConfirmClear] = useState(false);
  const [clearing, setClearing] = useState(false);

  const iframeRef = useRef(null);
  const stopRef = useRef(false);

  const load = async () => {
    const { data } = await api('/cookie-scan');
    setState(data.state);
    setCookies(data.cookies);
    setPostTypes(data.post_types);
    return data;
  };

  useEffect(() => {
    load()
      .then((data) => {
        // Only types the server allows (without Pro: posts and pages).
        const allowed = data.post_types.filter((t) => !t.locked).map((t) => t.value);
        const saved = (data.state.post_types || []).filter((t) => allowed.includes(t));
        setSelectedTypes(saved.length ? saved : allowed.filter((t) => ['post', 'page'].includes(t)));
      })
      .catch(() => Toast.error('Failed to load cookie scan data.'))
      .finally(() => setLoading(false));

    return () => {
      stopRef.current = true;
    };
  }, []);

  // Load one page in the hidden iframe and resolve once its collector reports (or times out).
  const scanPage = (url) =>
    new Promise((resolve) => {
      const iframe = iframeRef.current;
      let timer;
      const onMessage = (event) => {
        if (event.source === iframe?.contentWindow && event.data?.type === 'lp-cookie-scan-reported') {
          finish();
        }
      };
      const finish = () => {
        clearTimeout(timer);
        window.removeEventListener('message', onMessage);
        resolve();
      };
      window.addEventListener('message', onMessage);
      timer = setTimeout(finish, PAGE_TIMEOUT_MS);
      iframe.src = url;
    });

  const handleScan = async () => {
    stopRef.current = false;
    setScanning(true);
    try {
      const start = await api('/cookie-scan/start', { method: 'POST', body: { post_types: selectedTypes } });
      setState(start.data);

      while (!stopRef.current) {
        const { data } = await api('/cookie-scan/next', { method: 'POST' });
        setState(data.state);
        if (data.done) {
          break;
        }
        await scanPage(data.url);
      }

      if (iframeRef.current) {
        iframeRef.current.src = 'about:blank';
      }
      await load();
      if (!stopRef.current) {
        Toast.success('Cookie scan complete.');
      }
    } catch (e) {
      Toast.error(e.message || 'Cookie scan failed.');
    } finally {
      setScanning(false);
    }
  };

  const handleStop = async () => {
    stopRef.current = true;
    try {
      const { data } = await api('/cookie-scan/stop', { method: 'POST' });
      setState(data);
    } catch (e) {
      Toast.error('Failed to stop the scan.');
    }
  };

  const handleSync = async () => {
    setSyncing(true);
    try {
      const res = await api('/cookie-scan/sync', { method: 'POST' });
      setState(res.data.state);
      setCookies(res.data.cookies);
      if (res.success) {
        Toast.success(`Updated ${res.data.synced} cookies from cookiedatabase.org.`);
      } else {
        Toast.error(res.message || 'Sync failed.');
      }
    } catch (e) {
      Toast.error(e.message || 'Sync failed.');
    } finally {
      setSyncing(false);
    }
  };

  const handleClear = async () => {
    setClearing(true);
    try {
      const { data } = await api('/cookie-scan/cookies', { method: 'DELETE' });
      setState(data.state);
      setCookies(data.cookies);
      Toast.success('Cookies cleared.');
    } catch (e) {
      Toast.error('Failed to clear cookies.');
    } finally {
      setClearing(false);
      setConfirmClear(false);
    }
  };

  const handleUpdateCookie = async (id, changes) => {
    const previous = cookies;
    setCookies((list) => list.map((c) => (c.id === id ? { ...c, ...changes } : c)));
    try {
      const { data } = await api(`/cookie-scan/cookie/${id}`, { method: 'PUT', body: changes });
      setCookies((list) => list.map((c) => (c.id === id ? data : c)));
    } catch (e) {
      setCookies(previous);
      Toast.error('Failed to update cookie.');
    }
  };

  const toggleType = (value) =>
    setSelectedTypes((list) => (list.includes(value) ? list.filter((v) => v !== value) : [...list, value]));

  if (loading) {
    return (
      <SectionCard title="Website Cookie Scan" icon={<ScanIcon />}>
        <Skeleton />
      </SectionCard>
    );
  }

  return (
    <>
      <ScanPanel
        postTypes={postTypes}
        selectedTypes={selectedTypes}
        onToggleType={toggleType}
        state={state}
        cookies={cookies}
        scanning={scanning}
        syncing={syncing}
        onScan={handleScan}
        onStop={handleStop}
        onClear={() => setConfirmClear(true)}
        locked={locked}
        onLocked={onLocked}
        onSync={handleSync}
        onUpdateCookie={handleUpdateCookie}
        iframeRef={iframeRef}
      />
      <ConfirmationModal
        isOpen={confirmClear}
        onClose={() => setConfirmClear(false)}
        onConfirm={handleClear}
        title="Clear all scanned cookies?"
        message="This removes every cookie found by previous scans, including categories you changed by hand. Run a new scan to find them again."
        confirmText="Clear Cookies"
        isLoading={clearing}
      />
    </>
  );
};

export default CookieScanner;
