import React, { useState } from 'react';

// Fixed order (categorical slots 1-5), checked with the dataviz palette
// validator (light surface). Deny's aqua, GPC's yellow and Opt-out's magenta
// are under 3:1 against white, so every value is also in the tiles, the
// tooltip and the log table.
// GPC opt-out and Opt-out come from geo-targeted banners (Legal Pages Pro);
// they only show up once such records exist, and an older Pro doesn't send them.
export const CHOICES = [
  { key: 'accept_all', label: 'Accept all',  color: '#2a78d6' },
  { key: 'custom',     label: 'Custom',      color: '#eb6834' },
  { key: 'deny',       label: 'Deny',        color: '#1baf7a' },
  { key: 'gpc',        label: 'GPC opt-out', color: '#eda100', optional: true },
  { key: 'opt_out',    label: 'Opt-out',     color: '#e87ba4', optional: true },
];

// Choices the connected Pro reports (stats.totals keys); the first three always.
export const supportedChoices = (stats) =>
  CHOICES.filter((c) => !c.optional || (stats && stats.totals && c.key in stats.totals));

// A day's (or month's) total across every choice; missing keys count as 0.
const rowTotal = (row) => CHOICES.reduce((sum, c) => sum + (row[c.key] || 0), 0);

const pct = (part, total) => (total ? Math.round((part / total) * 1000) / 10 : 0);

const formatBucket = (bucket, type) => {
  const [y, m, d] = bucket.split('-').map(Number);
  const date = new Date(Date.UTC(y, m - 1, d || 1));
  return date.toLocaleDateString(undefined, type === 'month'
    ? { month: 'short', year: 'numeric', timeZone: 'UTC' }
    : { month: 'short', day: 'numeric', timeZone: 'UTC' });
};

const StatTile = ({ label, value, sub, color }) => (
  <div className="rounded-xl border border-[#E4E4E7] bg-white px-4 py-3">
    <div className="flex items-center gap-2 text-xs font-medium text-[#6F6F7B]">
      {color && <span className="inline-block h-2.5 w-2.5 rounded-sm" style={{ background: color }} />}
      {label}
    </div>
    <div className="mt-1 text-2xl font-semibold text-[#17171C]">{value}</div>
    {sub && <div className="text-xs text-[#6F6F7B]">{sub}</div>}
  </div>
);

/**
 * Accept / custom / deny (plus GPC opt-out / opt-out when there are any) totals
 * as tiles, plus a stacked bar per day (or month) with a hover tooltip.
 */
const ConsentChart = ({ stats }) => {
  const [hover, setHover] = useState(null);

  if (!stats) return null;

  const { totals, series, bucket } = stats;
  const count = (key) => totals[key] || 0;
  // The optional choices get a tile, legend entry and tooltip row only when there are some.
  const shown = CHOICES.filter((c) => !c.optional || count(c.key) > 0);
  const tileCols = { 3: 'md:grid-cols-4', 4: 'md:grid-cols-5', 5: 'md:grid-cols-3 xl:grid-cols-6' }[shown.length];
  const max = Math.max(1, ...series.map(rowTotal));
  const height = 180;
  const gap = series.length > 60 ? 1 : 2;

  return (
    <div className="space-y-5">
      <div className={`grid grid-cols-2 gap-3 ${tileCols}`}>
        <StatTile label="Consents recorded" value={totals.total.toLocaleString()} />
        {shown.map((c) => (
          <StatTile
            key={c.key}
            label={c.label}
            color={c.color}
            value={`${pct(count(c.key), totals.total)}%`}
            sub={`${count(c.key).toLocaleString()} ${count(c.key) === 1 ? 'choice' : 'choices'}`}
          />
        ))}
      </div>

      {totals.total === 0 ? (
        <div className="rounded-xl border border-dashed border-[#E4E4E7] py-10 text-center text-sm text-[#6F6F7B]">
          No consents recorded for these filters yet.
        </div>
      ) : (
        <div>
          <div className="mb-3 flex flex-wrap items-center gap-4 text-xs text-[#3F3F46]">
            {shown.map((c) => (
              <span key={c.key} className="inline-flex items-center gap-1.5">
                <span className="inline-block h-2.5 w-2.5 rounded-sm" style={{ background: c.color }} />
                {c.label}
              </span>
            ))}
            <span className="ml-auto text-[#6F6F7B]">Per {bucket}, site time zone</span>
          </div>

          <div className="relative" onMouseLeave={() => setHover(null)}>
            <div className="flex items-end border-b border-[#E4E4E7]" style={{ height, gap }}>
              {series.map((s, i) => {
                const total = rowTotal(s);
                return (
                  <div
                    key={s.bucket}
                    className="relative flex h-full min-w-0 flex-1 cursor-default flex-col justify-end"
                    onMouseEnter={() => setHover(i)}
                  >
                    {/* Wider-than-mark hit area: the whole column. */}
                    <div
                      className={`flex flex-col-reverse overflow-hidden rounded-t-[4px] ${hover === i ? 'opacity-100' : hover === null ? 'opacity-100' : 'opacity-60'}`}
                      style={{ height: `${(total / max) * 100}%`, gap: total ? 2 : 0 }}
                    >
                      {CHOICES.map((c) => (s[c.key] || 0) > 0 && (
                        <div key={c.key} style={{ flexGrow: s[c.key], flexBasis: 0, background: c.color, minHeight: 2 }} />
                      ))}
                    </div>
                  </div>
                );
              })}
            </div>

            {hover !== null && series[hover] && (() => {
              const s = series[hover];
              const total = rowTotal(s);
              const left = ((hover + 0.5) / series.length) * 100;
              return (
                <div
                  className="pointer-events-none absolute top-0 z-10 w-44 rounded-lg border border-[#E4E4E7] bg-white p-3 text-xs shadow-lg"
                  style={{ left: `${left}%`, transform: `translateX(${left > 70 ? '-105%' : '5%'})` }}
                >
                  <div className="mb-1.5 font-semibold text-[#17171C]">{formatBucket(s.bucket, bucket)}</div>
                  {shown.map((c) => (
                    <div key={c.key} className="flex items-center justify-between gap-2 py-0.5 text-[#3F3F46]">
                      <span className="inline-flex items-center gap-1.5">
                        <span className="inline-block h-2 w-2 rounded-sm" style={{ background: c.color }} />
                        {c.label}
                      </span>
                      <span className="font-medium text-[#17171C]">{s[c.key] || 0} ({pct(s[c.key] || 0, total)}%)</span>
                    </div>
                  ))}
                  <div className="mt-1 border-t border-[#F4F4F5] pt-1 text-[#6F6F7B]">Total {total}</div>
                </div>
              );
            })()}
          </div>

          <div className="mt-1.5 flex justify-between text-[11px] text-[#6F6F7B]">
            <span>{series.length ? formatBucket(series[0].bucket, bucket) : ''}</span>
            <span>max {max} / {bucket}</span>
            <span>{series.length ? formatBucket(series[series.length - 1].bucket, bucket) : ''}</span>
          </div>
        </div>
      )}
    </div>
  );
};

export default ConsentChart;
