import React from 'react';
import ProFeatureBanner from '../../../components/common/ProFeatureBanner';
import { usePromo, promoDarkCard, BoltIcon, PromoButton } from '../../../components/common/BlackFriday';

const NoticeBox = ({ title, description, href, label }) => (
  <div className="mb-6 flex max-w-[1150px] flex-col gap-5 rounded-2xl border border-amber-200 bg-amber-50 p-6 sm:flex-row sm:items-center sm:justify-between">
    <div>
      <h3 className="!mb-1 !text-[16px] !font-semibold !text-[#17171C]">{title}</h3>
      <p className="!text-sm !text-[#6F6F7B]">{description}</p>
    </div>
    {href && (
      <a
        href={href}
        className="inline-flex shrink-0 items-center gap-2 whitespace-nowrap rounded-xl bg-[#7C3BED] px-5 py-3 text-sm font-semibold !text-white no-underline transition hover:bg-indigo-700"
      >
        {label}
      </a>
    )}
  </div>
);

/** Black Friday 2026 version of the upgrade box (remove after the sale). */
const PromoLockBanner = ({ promo, count }) => (
  <div className={`relative mb-6 flex max-w-[1150px] flex-col gap-5 overflow-hidden rounded-2xl ${promoDarkCard} p-6 sm:flex-row sm:items-center sm:justify-between`}>
    <div className="flex items-center gap-4">
      <span className="flex h-14 w-14 shrink-0 items-center justify-center rounded-full bg-[#FCD34D1F] text-[#FCD34D]">
        <BoltIcon className="h-6 w-6" />
      </span>
      <div>
        <span className="text-[11px] font-extrabold uppercase tracking-[0.14em] text-[#FCD34D]">
          Black Friday · {promo.off} off · Ends in {promo.leftText}
        </span>
        <h3 className="!mb-1 !mt-1 !text-[18px] !font-bold !text-white">
          {count > 0
            ? `Your privacy policy is missing ${count} ${count === 1 ? 'service' : 'services'}`
            : 'Keep your privacy policy in step with your site'}
        </h3>
        <p className="!m-0 !text-sm !text-[#E4E4E7]">
          {count > 0
            ? `Get Pro for ${promo.off} off and add ${count === 1 ? 'it' : 'them'} automatically, plus every service you add later.`
            : `Get Pro for ${promo.off} off and add the services your site uses to your privacy policy automatically.`}
        </p>
      </div>
    </div>
    <div className="flex shrink-0 flex-col items-start gap-2 sm:items-end">
      <PromoButton promo={promo} className="!py-3">
        {count > 0 ? `Fix it for ${promo.off} off` : `Get Pro for ${promo.off} off`}
      </PromoButton>
      <span className="text-xs text-[#A1A1AA]">Lifetime plans included</span>
    </div>
  </div>
);

/** Why the controls are locked. Someone who already has Pro never sees an upgrade box. */
const LockBanner = ({ lock, count, updateUrl }) => {
  const promo = usePromo();

  if (lock === 'update') {
    return (
      <NoticeBox
        title="Update Legal Pages Pro to use Smart Policy"
        description="Your Legal Pages Pro version doesn't have Smart Policy yet. The list below is ready for when you update."
        href={updateUrl}
        label="Update Legal Pages Pro"
      />
    );
  }

  if (lock === 'license') {
    return (
      <NoticeBox
        title="Activate your Legal Pages Pro license"
        description="Your policy keeps showing the services it has now. Activate your license to change them and to hear about new ones."
        href="#/license"
        label="Activate License"
      />
    );
  }

  if (promo) {
    return <PromoLockBanner promo={promo} count={count} />;
  }

  return (
    <ProFeatureBanner
      className="mb-6"
      title={count > 0
        ? `Your privacy policy is missing ${count} ${count === 1 ? 'service' : 'services'}`
        : 'Keep your privacy policy in step with your site'}
      description={count > 0
        ? 'Upgrade to Pro to add them automatically.'
        : 'Upgrade to Pro to add the services your site uses to your privacy policy automatically.'}
    />
  );
};

export default LockBanner;
