import React, { useState, useEffect, useCallback } from 'react';
import { Toast } from '../../../../components/common/Toast';
import SectionCard from '../../../../components/common/SectionCard';
import ToggleField from '../../../../components/common/ToggleField';
import Skeleton from '../../../../components/common/Skeleton';
import { GlobeIcon } from '../../../../components/common/SvgIcon';

const primaryBtn =
  'inline-flex cursor-pointer items-center justify-center rounded-xl bg-[#7C3BED] px-6 py-[11px] text-sm font-semibold text-white shadow-[0px_4px_14px_-2px_#7C3BED40] transition hover:bg-indigo-700 disabled:cursor-not-allowed disabled:bg-indigo-400';
const secondaryBtn =
  'inline-flex cursor-pointer items-center justify-center rounded-xl border border-[#E4E4E7] bg-white px-3.5 py-[11px] text-sm font-medium text-[#17171C] transition hover:bg-[#FAFAFA] disabled:cursor-not-allowed disabled:opacity-50';
const inputCls =
  '!h-[42px] !rounded-xl !border !border-[#E4E4E7] !bg-white !px-3 !text-sm !text-[#17171C] focus:!border-[#7C3BED] focus:!shadow-none';

const REGIONS = [
  { key: 'eu', label: 'EU / EEA', hint: 'GDPR' },
  { key: 'uk', label: 'United Kingdom', hint: 'UK GDPR' },
  { key: 'us', label: 'United States', hint: 'State privacy laws' },
  { key: 'other', label: 'Everyone else', hint: 'All other countries' },
];

const BANNERS = [
  { key: 'opt_in', label: 'Opt-in', help: 'Nothing optional runs until the visitor accepts.' },
  { key: 'opt_out', label: 'Opt-out notice', help: 'Categories below run at once; the visitor can opt out.' },
  { key: 'notice', label: 'Simple notice', help: 'Categories below run; the banner only informs (OK).' },
  { key: 'none', label: 'No banner', help: 'Categories below run; no banner (Manage consent still works).' },
];

const CATEGORIES = [
  { key: 'preferences', label: 'Preferences' },
  { key: 'statistics', label: 'Statistics' },
  { key: 'marketing', label: 'Marketing' },
];

const LINKS = [
  { key: 'cookie_policy', label: 'Cookie policy' },
  { key: 'privacy_policy', label: 'Privacy policy' },
  { key: 'do_not_sell', label: 'Do Not Sell or Share' },
];

const SOURCES = {
  cloudflare: 'Cloudflare header',
  cloudfront: 'Amazon CloudFront header',
  'wp-engine': 'WP Engine geolocation',
  geoip: 'Server geolocation (e.g. Kinsta)',
  'maxmind-module': 'Server MaxMind module',
  'app-engine': 'Google App Engine header',
  header: 'Geo request header',
  maxmind: 'MaxMind database',
  timezone: 'Browser time zone (no CDN or host location found)',
};

const api = (path, options = {}) =>
  fetch(`${LEGAL_PAGES.apiUrl}${path}`, {
    ...options,
    headers: { 'X-WP-Nonce': LEGAL_PAGES.nonce, ...(options.headers || {}) },
  });

const browserTimezone = () => {
  try {
    return Intl.DateTimeFormat().resolvedOptions().timeZone || '';
  } catch (e) {
    return '';
  }
};

const toggleIn = (list, key) => (list.includes(key) ? list.filter((k) => k !== key) : [...list, key]);

// Page dropdown label, marking drafts so an unpublished page is obvious.
const pageLabel = (p) => {
  const title = p.title?.rendered ? p.title.rendered.replace(/<[^>]+>/g, '') : `#${p.id}`;
  return p.status === 'draft' ? `${title} (draft)` : title;
};

const pageEditUrl = (id) => `${LEGAL_PAGES.admin_url}post.php?post=${id}&action=edit`;

// The F7 template behind "Create page" (seeded by Core\Activator, Pro template).
const DNS_TEMPLATE = 'Do Not Sell or Share My Personal Information';

/**
 * Geo-targeted banners (Pro): which banner each visitor region gets, Global
 * Privacy Control, and the "Do Not Sell or Share" link. Backend: Legal Pages
 * Pro's `/geo-rules` and `/geo` routes (LegalPagePro\Models\Geo_Rules,
 * LegalPagePro\Services\Geo).
 */
const Regions = () => {
  const [rules, setRules] = useState(null);
  const [statesText, setStatesText] = useState('');
  const [pages, setPages] = useState([]);
  const [saving, setSaving] = useState(false);
  const [unavailable, setUnavailable] = useState(false);
  const [test, setTest] = useState(null);
  const [testing, setTesting] = useState(false);
  const [testIp, setTestIp] = useState('');
  const [creatingPage, setCreatingPage] = useState(false);
  // The draft made by "Create page", so we can point at it to review/publish.
  const [createdDraft, setCreatedDraft] = useState(null);

  // MaxMind GeoLite2 (optional). `db` is the saved state from the server (never the
  // license key); `dbForm` is what's being typed. null = this Pro has no MaxMind support.
  const [db, setDb] = useState(null);
  const [dbForm, setDbForm] = useState({ account_id: '', license_key: '', edition: 'city', trust_proxy: false });
  const [dbBusy, setDbBusy] = useState('');
  // Collapsed until set up: most sites don't need MaxMind.
  const [dbOpen, setDbOpen] = useState(false);

  const load = useCallback(async () => {
    try {
      const res = await api('/geo-rules');
      if (res.status === 404) {
        // Legal Pages Pro older than geo-targeting.
        setUnavailable(true);
        return;
      }
      const result = await res.json();
      if (result.success) {
        setRules(result.data);
        setStatesText(result.data.gpc.states.join(', '));
      } else {
        Toast.error('Failed to load region settings');
      }
    } catch (e) {
      Toast.error('Failed to load region settings');
    }
  }, []);

  useEffect(() => { load(); }, [load]);

  // Published and draft pages for the "Do Not Sell or Share" / "Privacy policy" links.
  useEffect(() => {
    fetch(`${LEGAL_PAGES.rest_base}wp/v2/pages?status=publish,draft&per_page=100&orderby=title&order=asc&_fields=id,title,status`, {
      headers: { 'X-WP-Nonce': LEGAL_PAGES.nonce },
    })
      .then((r) => (r.ok ? r.json() : []))
      .then((list) => setPages(Array.isArray(list) ? list : []))
      .catch(() => setPages([]));
  }, []);

  const setRule = (region, patch) =>
    setRules((r) => ({ ...r, rules: { ...r.rules, [region]: { ...r.rules[region], ...patch } } }));

  const save = async () => {
    setSaving(true);
    try {
      const states = statesText.split(/[\s,]+/).map((s) => s.trim().toUpperCase()).filter(Boolean);
      const res = await api('/geo-rules', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...rules, gpc: { ...rules.gpc, states } }),
      });
      const result = await res.json();
      if (result.success) {
        setRules(result.data);
        setStatesText(result.data.gpc.states.join(', '));
        setTest(null);
        Toast.success('Region settings saved!');
      } else {
        Toast.error('Failed to save settings.');
      }
    } catch (e) {
      Toast.error('An error occurred while saving.');
    } finally {
      setSaving(false);
    }
  };

  // "Create page": a legal page from the Do Not Sell template, saved as a draft and set as
  // the banner's link. The link only appears once the page is published, so the admin
  // reviews it first. Only `do_not_sell_page` is saved (on top of the stored rules), so other
  // unsaved edits on this tab stay unsaved.
  const createDnsPage = async () => {
    setCreatingPage(true);
    try {
      const found = await api(`/templates?type=pro&per_page=50&search=${encodeURIComponent(DNS_TEMPLATE)}`).then((r) => r.json());
      const template = (found.data?.templates || []).find((t) => t.name === DNS_TEMPLATE);
      if (!template) {
        Toast.error(`The "${DNS_TEMPLATE}" template wasn't found under Legal Page Templates.`);
        return;
      }

      const created = await api('/legal-page', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title: DNS_TEMPLATE, content: template.content, status: 'draft' }),
      }).then((r) => r.json());
      if (!created.success) {
        Toast.error('Failed to create the page.');
        return;
      }
      const page = created.data;

      const stored = await api('/geo-rules').then((r) => r.json());
      const saved = stored.success && await api('/geo-rules', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...stored.data, do_not_sell_page: page.id }),
      }).then((r) => r.json());

      setPages((list) => [...list, { id: page.id, title: { rendered: page.title }, status: 'draft' }]);
      setRules((r) => ({ ...r, do_not_sell_page: page.id }));
      setCreatedDraft({ id: page.id, edit_url: page.edit_url, title: page.title });
      if (saved && saved.success) {
        Toast.success('Draft page created — review and publish it to show the link.');
      } else {
        Toast.error('Draft page created, but the setting wasn\'t saved. Click Save Settings.');
      }
    } catch (e) {
      Toast.error('An error occurred while creating the page.');
    } finally {
      setCreatingPage(false);
    }
  };

  // `ip` set = "Test an IP address" (MaxMind only); empty = this browser's own location.
  const testLocation = async (ip = '') => {
    setTesting(true);
    try {
      const qs = ip ? `ip=${encodeURIComponent(ip)}` : `timezone=${encodeURIComponent(browserTimezone())}`;
      const res = await api(`/geo?${qs}`);
      const result = await res.json();
      setTest(result.success ? { ...result.data, testedIp: ip } : null);
    } catch (e) {
      Toast.error('Could not check the location.');
    } finally {
      setTesting(false);
    }
  };

  const applyDb = (data) => {
    setDb(data);
    if (data.has_key || data.available) setDbOpen(true);
    setDbForm({ account_id: data.account_id, license_key: '', edition: data.edition, trust_proxy: data.trust_proxy });
  };

  useEffect(() => {
    api('/geo-database')
      .then((r) => (r.ok ? r.json() : null))
      .then((result) => result && result.success && applyDb(result.data))
      .catch(() => {});
  }, []);

  // download = true: save, then fetch the database from MaxMind now.
  const saveDb = async (download) => {
    setDbBusy(download ? 'download' : 'save');
    try {
      const res = await api('/geo-database', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...dbForm, download }),
      });
      const result = await res.json();
      if (result.data) applyDb(result.data);
      if (result.success) {
        Toast.success(download ? 'Location database downloaded!' : 'Location database settings saved!');
      } else {
        Toast.error(result.message || 'Download failed.');
      }
    } catch (e) {
      Toast.error('An error occurred while contacting the server.');
    } finally {
      setDbBusy('');
    }
  };

  const removeDb = async () => {
    setDbBusy('remove');
    try {
      const res = await api('/geo-database', { method: 'DELETE' });
      const result = await res.json();
      if (result.success) {
        applyDb(result.data);
        setDbOpen(false);
        Toast.success('Location database removed.');
      }
    } catch (e) {
      Toast.error('An error occurred while removing.');
    } finally {
      setDbBusy('');
    }
  };

  if (unavailable) {
    return (
      <SectionCard title="Geo-targeted banners" icon={<GlobeIcon />} maxHeight="">
        <p className="!text-sm !text-[#6F6F7B]">
          Update Legal Pages Pro to show each visitor the banner that fits their region.
        </p>
      </SectionCard>
    );
  }

  if (!rules) {
    return (
      <SectionCard title="Geo-targeted banners" icon={<GlobeIcon />} maxHeight="">
        <Skeleton />
      </SectionCard>
    );
  }

  const regionLabel = (key) => REGIONS.find((r) => r.key === key)?.label || key;
  const bannerLabel = (key) => BANNERS.find((b) => b.key === key)?.label || key;

  // The chosen Do Not Sell page, if it still exists as a draft, so we can prompt a publish.
  const dnsIsDraft = rules.do_not_sell_page
    ? pages.some((p) => p.id === rules.do_not_sell_page && p.status === 'draft')
    : false;
  const dnsEditUrl = createdDraft?.id === rules.do_not_sell_page
    ? createdDraft.edit_url
    : pageEditUrl(rules.do_not_sell_page);

  // Privacy Policy link: the picked page if published, else Settings → Privacy. Warn when
  // a region shows the link but neither gives a page, since the link then just disappears.
  // `wp_privacy_url` is undefined with an older Pro's localized data: no warning then.
  const privacyIsDraft = rules.privacy_policy_page
    ? pages.some((p) => p.id === rules.privacy_policy_page && p.status === 'draft')
    : false;
  const privacyShown = REGIONS.some(({ key }) => rules.rules[key].links.includes('privacy_policy'));
  const noWpPrivacy = LEGAL_PAGES.wp_privacy_url === '';

  return (
    <div className="space-y-6">
      <SectionCard title="Geo-targeted banners" icon={<GlobeIcon />} maxHeight="">
        <div className="space-y-5">
          <p className="!text-sm !text-[#6F6F7B]">
            Show each visitor the banner their region's law expects: opt-in in the EU and UK, an opt-out notice with a
            "Do Not Sell or Share" link in the US, and a simple notice elsewhere. The visitor's region comes from your CDN
            or host when they provide it, otherwise from the browser's time zone. Pages stay cacheable: the banner asks
            for the visitor's rule after the page loads. When this is off, everyone gets the opt-in banner.
          </p>

          <ToggleField
            label="Geo-targeted banners"
            description="Show the banner that fits each visitor's region"
            name="enabled"
            checked={rules.enabled}
            onChange={(name, value) => setRules((r) => ({ ...r, [name]: value }))}
          />

          {/* Rules per region */}
          <div className="overflow-x-auto rounded-xl border border-[#E4E4E7]">
            <table className="w-full min-w-[760px] text-left text-sm">
              <thead className="bg-[#FAFAFA] text-xs text-[#6F6F7B]">
                <tr>
                  <th className="px-4 py-3 font-medium">Region</th>
                  <th className="px-4 py-3 font-medium">Banner</th>
                  <th className="px-4 py-3 font-medium">On before the visitor chooses</th>
                  <th className="px-4 py-3 font-medium">Links in the banner</th>
                </tr>
              </thead>
              <tbody>
                {REGIONS.map(({ key, label, hint }) => {
                  const rule = rules.rules[key];
                  const optIn = rule.banner === 'opt_in';
                  return (
                    <tr key={key} className="border-t border-[#F4F4F5] align-top">
                      <td className="px-4 py-3">
                        <div className="font-medium text-[#17171C]">{label}</div>
                        <div className="text-xs text-[#6F6F7B]">{hint}</div>
                      </td>
                      <td className="px-4 py-3">
                        <select
                          className={`${inputCls} !pr-8`}
                          value={rule.banner}
                          onChange={(e) => setRule(key, { banner: e.target.value })}
                          aria-label={`Banner for ${label}`}
                        >
                          {BANNERS.map((b) => <option key={b.key} value={b.key}>{b.label}</option>)}
                        </select>
                        <div className="mt-1 max-w-[220px] text-xs text-[#6F6F7B]">{BANNERS.find((b) => b.key === rule.banner)?.help}</div>
                      </td>
                      <td className="px-4 py-3">
                        {optIn ? (
                          <span className="text-xs text-[#6F6F7B]">Nothing until the visitor accepts</span>
                        ) : (
                          <div className="flex flex-col gap-1.5">
                            {CATEGORIES.map((c) => (
                              <label key={c.key} className="flex items-center gap-2 text-sm text-[#17171C]">
                                <input
                                  type="checkbox"
                                  checked={rule.categories.includes(c.key)}
                                  onChange={() => setRule(key, { categories: toggleIn(rule.categories, c.key) })}
                                />
                                {c.label}
                              </label>
                            ))}
                          </div>
                        )}
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex flex-col gap-1.5">
                          {LINKS.map((l) => (
                            <label key={l.key} className="flex items-center gap-2 text-sm text-[#17171C]">
                              <input
                                type="checkbox"
                                checked={rule.links.includes(l.key)}
                                onChange={() => setRule(key, { links: toggleIn(rule.links, l.key) })}
                              />
                              {l.label}
                            </label>
                          ))}
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
          <p className="!text-xs !text-[#6F6F7B]">
            Only the categories your banner offers (General Settings) are used. Links appear only when their page exists:
            the cookie policy link from General Settings, the privacy policy page picked below (or WordPress's Settings →
            Privacy page), and the "Do Not Sell or Share" page below.
          </p>

          {/* Fallback */}
          <label className="flex max-w-[460px] flex-col gap-1.5 text-sm font-medium text-[#17171C]">
            If a visitor's region can't be detected, use the rule for
            <select
              className={`${inputCls} !pr-8`}
              value={rules.fallback}
              onChange={(e) => setRules((r) => ({ ...r, fallback: e.target.value }))}
            >
              {REGIONS.map((r) => (
                <option key={r.key} value={r.key}>{r.label}{r.key === 'eu' ? ' (strictest, recommended)' : ''}</option>
              ))}
            </select>
          </label>

          {/* GPC */}
          <div className="space-y-3 border-t border-[#F4F4F5] pt-5">
            <ToggleField
              label="Honor Global Privacy Control (GPC)"
              description="Browsers that send GPC get Marketing turned off automatically in the US, without a click, and it's recorded in the consent log"
              name="enabled"
              checked={rules.gpc.enabled}
              onChange={(name, value) => setRules((r) => ({ ...r, gpc: { ...r.gpc, enabled: value } }))}
            />
            <label className="flex flex-col gap-1.5 text-sm font-medium text-[#17171C]">
              US states whose laws require it
              <input
                type="text"
                className={inputCls}
                value={statesText}
                onChange={(e) => setStatesText(e.target.value)}
                placeholder="CA, CO, CT"
                disabled={!rules.gpc.enabled}
              />
            </label>
            <p className="!text-xs !text-[#6F6F7B]">
              Two-letter state codes, separated by commas. US visitors whose state can't be detected are always covered.
              Please have your legal advisor confirm this list.
            </p>
          </div>

          {/* Do Not Sell / Privacy policy pages + texts */}
          <div className="grid grid-cols-1 gap-4 border-t border-[#F4F4F5] pt-5 md:grid-cols-2 lg:grid-cols-4">
            <div className="flex flex-col gap-1.5">
              <label className="flex flex-col gap-1.5 text-sm font-medium text-[#17171C]">
                "Do Not Sell or Share" page
                <select
                  className={`${inputCls} !pr-8`}
                  value={rules.do_not_sell_page || 0}
                  onChange={(e) => setRules((r) => ({ ...r, do_not_sell_page: Number(e.target.value) }))}
                >
                  <option value={0}>— None —</option>
                  {pages.map((p) => (
                    <option key={p.id} value={p.id}>{pageLabel(p)}</option>
                  ))}
                </select>
              </label>
              {!rules.do_not_sell_page ? (
                <div className="flex flex-col items-start gap-1.5">
                  <button type="button" className={secondaryBtn} onClick={createDnsPage} disabled={creatingPage}>
                    {creatingPage ? 'Creating...' : 'Create page'}
                  </button>
                  <span className="text-xs text-[#6F6F7B]">
                    Creates a draft page from the "{DNS_TEMPLATE}" template, with the opt-out button, and uses it here.
                  </span>
                </div>
              ) : dnsIsDraft ? (
                <span className="text-xs text-amber-700">
                  This page is a draft — the banner link stays hidden until you publish it.{' '}
                  <a href={dnsEditUrl} target="_blank" rel="noopener noreferrer" className="underline">Review / publish the page</a>
                </span>
              ) : !REGIONS.some(({ key }) => rules.rules[key].links.includes('do_not_sell')) && (
                <span className="text-xs text-amber-700">
                  No region shows this link yet: tick "Do Not Sell or Share" under Links in the banner (usually United States).
                </span>
              )}
            </div>
            <label className="flex flex-col gap-1.5 text-sm font-medium text-[#17171C]">
              Privacy policy page
              <select
                className={`${inputCls} !pr-8`}
                value={rules.privacy_policy_page || 0}
                onChange={(e) => setRules((r) => ({ ...r, privacy_policy_page: Number(e.target.value) }))}
              >
                <option value={0}>— WordPress default (Settings → Privacy) —</option>
                {pages.map((p) => (
                  <option key={p.id} value={p.id}>{pageLabel(p)}</option>
                ))}
              </select>
              <span className="text-xs font-normal text-[#6F6F7B]">
                The page the banner's "Privacy Policy" link points at. Leave as the WordPress default to use Settings → Privacy.
              </span>
              {privacyIsDraft ? (
                <span className="text-xs font-normal text-amber-700">
                  This page is a draft, so the banner {noWpPrivacy ? 'shows no Privacy Policy link' : 'links the Settings → Privacy page instead'} until you publish it.{' '}
                  <a href={pageEditUrl(rules.privacy_policy_page)} target="_blank" rel="noopener noreferrer" className="underline">Review / publish the page</a>
                </span>
              ) : !rules.privacy_policy_page && noWpPrivacy && privacyShown && (
                <span className="text-xs font-normal text-amber-700">
                  WordPress has no privacy policy page set (Settings → Privacy), so the banner's Privacy Policy link is hidden. Pick your privacy policy page here.
                </span>
              )}
            </label>
            <label className="flex flex-col gap-1.5 text-sm font-medium text-[#17171C]">
              Notice button text
              <input
                type="text"
                className={inputCls}
                value={rules.texts.ok}
                placeholder="OK"
                onChange={(e) => setRules((r) => ({ ...r, texts: { ...r.texts, ok: e.target.value } }))}
              />
            </label>
            <label className="flex flex-col gap-1.5 text-sm font-medium text-[#17171C]">
              Opt-out button text
              <input
                type="text"
                className={inputCls}
                value={rules.texts.opt_out}
                placeholder="Opt out"
                onChange={(e) => setRules((r) => ({ ...r, texts: { ...r.texts, opt_out: e.target.value } }))}
              />
            </label>
          </div>

          <button type="button" className={primaryBtn} onClick={save} disabled={saving}>
            {saving ? 'Saving...' : 'Save Settings'}
          </button>
        </div>
      </SectionCard>

      {/* MaxMind GeoLite2 (optional) — hidden with a Pro that doesn't support it. */}
      {db && (
        <SectionCard
          title={(
            <span className="inline-flex items-center gap-2">
              Location database (MaxMind)
              <span className="rounded-full bg-[#F4F4F5] px-2 py-0.5 text-xs font-medium text-[#6F6F7B]">Optional</span>
            </span>
          )}
          icon={<GlobeIcon />}
          maxHeight=""
        >
          {!dbOpen ? (
            <div className="flex flex-wrap items-center justify-between gap-4">
              <p className="max-w-[760px] !text-sm !text-[#6F6F7B]">
                Improves location accuracy on sites without Cloudflare or a host that sends the visitor's location, using
                MaxMind's GeoLite2 database (needs a MaxMind account). Most sites don't need this.
              </p>
              <button type="button" className={secondaryBtn} onClick={() => setDbOpen(true)}>Set up</button>
            </div>
          ) : (
          <div className="space-y-5">
            <p className="!text-sm !text-[#6F6F7B]">
              Without Cloudflare or a host that sends the visitor's location, the region comes from the browser's
              time zone, which can be wrong and never tells the US state. With MaxMind's free GeoLite2 database the visitor's
              IP is looked up on your own server: it isn't sent anywhere and isn't stored.{' '}
              <a href="https://www.maxmind.com/en/geolite2/signup" target="_blank" rel="noopener noreferrer" className="!text-[#7C3BED] underline">
                Create a free MaxMind account
              </a>
              , then generate a license key under "Manage license keys". The database is refreshed every week.
            </p>

            {!db.phar && (
              <p className="rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 !text-sm !text-[#17171C]">
                Your server's PHP is missing the Phar extension, which is needed to unpack the MaxMind download. Ask your host to enable it.
              </p>
            )}

            <div className="grid grid-cols-1 gap-4 md:grid-cols-3">
              <label className="flex flex-col gap-1.5 text-sm font-medium text-[#17171C]">
                MaxMind account ID
                <input
                  type="text"
                  inputMode="numeric"
                  autoComplete="off"
                  className={inputCls}
                  value={dbForm.account_id}
                  placeholder="123456"
                  onChange={(e) => setDbForm((f) => ({ ...f, account_id: e.target.value }))}
                />
              </label>
              <label className="flex flex-col gap-1.5 text-sm font-medium text-[#17171C]">
                License key
                <input
                  type="password"
                  autoComplete="new-password"
                  className={inputCls}
                  value={dbForm.license_key}
                  placeholder={db.has_key ? 'Saved (leave empty to keep it)' : 'Your MaxMind license key'}
                  onChange={(e) => setDbForm((f) => ({ ...f, license_key: e.target.value }))}
                />
              </label>
              <label className="flex flex-col gap-1.5 text-sm font-medium text-[#17171C]">
                Database
                <select
                  className={`${inputCls} !pr-8`}
                  value={dbForm.edition}
                  onChange={(e) => setDbForm((f) => ({ ...f, edition: e.target.value }))}
                >
                  <option value="city">City — includes US states (recommended)</option>
                  <option value="country">Country — smaller, no states</option>
                </select>
              </label>
            </div>

            <ToggleField
              label="My site is behind a proxy or load balancer"
              description="Only turn this on if your host says so. The visitor's IP is then read from the X-Forwarded-For header, which visitors could otherwise fake."
              name="trust_proxy"
              checked={dbForm.trust_proxy}
              onChange={(name, value) => setDbForm((f) => ({ ...f, [name]: value }))}
            />

            <div className="flex flex-wrap gap-3">
              <button
                type="button"
                className={primaryBtn}
                onClick={() => saveDb(true)}
                disabled={dbBusy !== '' || !db.phar || !dbForm.account_id.trim() || (!dbForm.license_key.trim() && !db.has_key)}
              >
                {dbBusy === 'download' ? 'Downloading...' : 'Save & download'}
              </button>
              <button type="button" className={secondaryBtn} onClick={() => saveDb(false)} disabled={dbBusy !== ''}>
                {dbBusy === 'save' ? 'Saving...' : 'Save'}
              </button>
              {(db.has_key || db.available) ? (
                <button type="button" className={secondaryBtn} onClick={removeDb} disabled={dbBusy !== ''}>
                  {dbBusy === 'remove' ? 'Removing...' : 'Remove database and key'}
                </button>
              ) : (
                <button type="button" className={secondaryBtn} onClick={() => setDbOpen(false)} disabled={dbBusy !== ''}>
                  Cancel
                </button>
              )}
            </div>

            <dl className="grid grid-cols-2 gap-3 border-t border-[#F4F4F5] pt-4 text-sm md:grid-cols-4">
              <div>
                <dt className="text-xs text-[#6F6F7B]">Database</dt>
                <dd className="font-semibold text-[#17171C]">{db.available ? db.status.edition : 'Not downloaded'}</dd>
              </div>
              <div>
                <dt className="text-xs text-[#6F6F7B]">Data from (MaxMind)</dt>
                <dd className="font-semibold text-[#17171C]">{db.available ? `${db.status.built.slice(0, 10)}` : '—'}</dd>
              </div>
              <div>
                <dt className="text-xs text-[#6F6F7B]">Downloaded</dt>
                <dd className="font-semibold text-[#17171C]">
                  {db.available ? `${db.status.updated.slice(0, 16)} UTC · ${(db.status.size / 1048576).toFixed(1)} MB` : '—'}
                </dd>
              </div>
              <div>
                <dt className="text-xs text-[#6F6F7B]">Next update</dt>
                <dd className="font-semibold text-[#17171C]">{db.next ? `${db.next.slice(0, 16)} UTC` : '—'}</dd>
              </div>
            </dl>
            {db.status.error && (
              <p className="!text-sm !text-red-600">
                Last download failed: {db.status.error}{db.available ? ' The previously downloaded database is still in use.' : ''}
              </p>
            )}

            <p className="!text-xs !text-[#6F6F7B]">
              This product includes GeoLite2 Data created by MaxMind, available from{' '}
              <a href="https://www.maxmind.com" target="_blank" rel="noopener noreferrer" className="underline">https://www.maxmind.com</a>.
            </p>
          </div>
          )}
        </SectionCard>
      )}

      {/* Test my location */}
      <SectionCard title="Test my location" icon={<GlobeIcon />} maxHeight="">
        <div className="space-y-4">
          <p className="!text-sm !text-[#6F6F7B]">
            See which region and banner your own browser gets, and where the location came from. Save your settings first.
            {db?.available && ' With the MaxMind database you can also test any public IP address, for example one from another country.'}
          </p>
          <div className="flex flex-wrap items-end gap-3">
            <button type="button" className={secondaryBtn} onClick={() => testLocation()} disabled={testing}>
              {testing ? 'Checking...' : 'Test my location'}
            </button>
            {db?.available && (
              <>
                <label className="flex flex-col gap-1.5 text-sm font-medium text-[#17171C]">
                  Test an IP address
                  <input
                    type="text"
                    className={inputCls}
                    value={testIp}
                    placeholder="e.g. 81.2.69.142"
                    onChange={(e) => setTestIp(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && testIp.trim() && testLocation(testIp.trim())}
                  />
                </label>
                <button type="button" className={secondaryBtn} onClick={() => testLocation(testIp.trim())} disabled={testing || !testIp.trim()}>
                  Test IP
                </button>
              </>
            )}
          </div>
          {test && (test.enabled ? (
            <dl className="grid grid-cols-2 gap-3 border-t border-[#F4F4F5] pt-4 text-sm md:grid-cols-4">
              <div>
                <dt className="text-xs text-[#6F6F7B]">Detected {test.testedIp ? `for ${test.testedIp}` : 'for your browser'}</dt>
                <dd className="font-semibold text-[#17171C]">
                  {test.location?.country
                    ? `${test.location.country}${test.location.state ? `-${test.location.state}` : ''}`
                    : test.location?.timezone || (test.testedIp ? 'Not found in the database' : 'Unknown')}
                </dd>
              </div>
              <div>
                <dt className="text-xs text-[#6F6F7B]">From</dt>
                <dd className="font-semibold text-[#17171C]">{SOURCES[test.location?.source] || 'Nothing (fallback rule)'}</dd>
              </div>
              <div>
                <dt className="text-xs text-[#6F6F7B]">Rule</dt>
                <dd className="font-semibold text-[#17171C]">
                  {regionLabel(test.rule)}{!test.region ? ' (fallback)' : ''} · {bannerLabel(test.banner)}
                </dd>
              </div>
              <div>
                <dt className="text-xs text-[#6F6F7B]">Global Privacy Control</dt>
                <dd className="font-semibold text-[#17171C]">
                  {test.gpc ? 'Honored here' : 'Not applied here'}
                  {!test.testedIp && ` · your browser ${navigator.globalPrivacyControl === true ? 'sends it' : "doesn't send it"}`}
                </dd>
              </div>
            </dl>
          ) : (
            <p className="flex items-center gap-2 !text-sm !text-[#6F6F7B]">
              Geo-targeted banners are off. Turn them on and save to test.
            </p>
          ))}
        </div>
      </SectionCard>
    </div>
  );
};

export default Regions;
