import React, { useState } from 'react';

const CloseIcon = () => (
  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" aria-hidden="true">
    <path d="M18 6 6 18M6 6l12 12" />
  </svg>
);

/**
 * "New service detected" notice (Legal Pages Pro). It lives in the SPA, so it can
 * only ever show on our own screens. `notice.covered` is true only when a published
 * page holds the tag: before that, saying the policy covers a service would be false.
 *
 * Closing it clears Pro's pending list for the whole site; a later new service sets
 * it again. App reads LEGAL_PAGES.smart_policy_notice on each screen change, and the
 * localized object outlives hash navigation, so the closed notice stays closed.
 */
const SmartPolicyNotice = ({ notice, wrapperClassName = 'px-8 pt-6', showLink = true }) => {
  const [dismissed, setDismissed] = useState(false);

  if (dismissed || !notice?.services?.length) {
    return null;
  }

  const many = notice.services.length > 1;
  // A first run after an update can find a dozen services; name a few, count the rest.
  const SHOWN = 3;
  const extra = notice.services.length - SHOWN;
  const names = extra > 1
    ? `${notice.services.slice(0, SHOWN).join(', ')} and ${extra} more`
    : notice.services.join(', ');

  const dismiss = () => {
    setDismissed(true);
    LEGAL_PAGES.smart_policy_notice = null;
    fetch(`${LEGAL_PAGES.apiUrl}/smart-policy/notice/dismiss`, {
      method: 'POST',
      headers: { 'X-WP-Nonce': LEGAL_PAGES.nonce },
    }).catch(() => {});
  };

  return (
    <div className={wrapperClassName}>
      <div className="relative flex max-w-[1150px] flex-col gap-3 rounded-2xl border border-indigo-100 bg-[#7C3BED0D] py-4 pl-5 pr-12 sm:flex-row sm:items-center sm:justify-between">
        <p className="!m-0 !text-sm !font-medium !text-[#17171C]">
          <span title={many ? notice.services.join(', ') : undefined}>{`New ${many ? 'services' : 'service'} detected: ${names}. `}</span>
          {notice.covered
            ? `Your privacy policy now covers ${many ? 'them' : 'it'}.`
            : <>Add <code>[lp_smart_policy]</code> to your privacy policy page so it covers {many ? 'them' : 'it'}.</>}
        </p>
        {showLink && (
          <a
            href="#/smart-policy"
            className="inline-flex shrink-0 items-center justify-center rounded-xl bg-[#7C3BED] px-5 py-2.5 text-sm !font-bold !text-white no-underline shadow-[0px_4px_14px_-2px_#7C3BED40] transition hover:bg-indigo-700"
          >
            Review
          </a>
        )}
        <button
          type="button"
          onClick={dismiss}
          aria-label="Dismiss this notice"
          className="absolute right-3 top-3 flex h-7 w-7 cursor-pointer items-center justify-center rounded-lg border-0 bg-transparent text-[#6F6F7B] transition hover:bg-[#7C3BED1A] hover:text-[#17171C] sm:top-1/2 sm:-translate-y-1/2"
        >
          <CloseIcon />
        </button>
      </div>
    </div>
  );
};

export default SmartPolicyNotice;
