import React, { useState, useEffect } from 'react';

import { Toast } from '../../components/common/Toast';
import DisclaimerScreen from '../Settings/components/DisclaimerScreen';
import WizardStepper from './components/WizardStepper';
import StepBusinessInfo from './components/StepBusinessInfo';
import StepCreatePage from './components/StepCreatePage';
import StepComplete from './components/StepComplete';

const STEPS = [
  { id: 1, label: 'Business Information' },
  { id: 2, label: 'Create a Legal Page' },
  { id: 3, label: 'Done' },
];

const SetupWizard = () => {
  const [isLoading, setIsLoading] = useState(true);
  const [showDisclaimer, setShowDisclaimer] = useState(false);
  const [acceptedDisclaimer, setAcceptedDisclaimer] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  const [currentStep, setCurrentStep] = useState(1);
  const [createdPage, setCreatedPage] = useState(null);
  const [skipping, setSkipping] = useState(false);

  // "I'll set up later": record the wizard as handled, then go to Settings.
  const handleSkip = async () => {
    setSkipping(true);
    try {
      await fetch(`${LEGAL_PAGES.apiUrl}/setup-wizard/complete`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-WP-Nonce': LEGAL_PAGES.nonce,
        },
      });
    } catch (error) {
      console.error('Error skipping setup wizard:', error);
    } finally {
      window.location.hash = '/';
    }
  };

  useEffect(() => {
    const disclaimerAccepted = LEGAL_PAGES?.status;

    if (String(disclaimerAccepted) === '1') {
      setAcceptedDisclaimer(true);
    } else {
      setShowDisclaimer(true);
    }

    setIsLoading(false);
  }, []);

  const handleDisclaimerAccept = async () => {
    setSubmitting(true);
    adl_legal_pages__modal(true);

    try {
      const response = await fetch(`${LEGAL_PAGES.apiUrl}/accept`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-WP-Nonce': LEGAL_PAGES.nonce,
        },
      });

      const result = await response.json();

      if (result.success) {
        // Keep the page-load copy in sync so other SPA screens don't show the disclaimer again.
        window.LEGAL_PAGES.status = '1';
        setAcceptedDisclaimer(true);
        setShowDisclaimer(false);
        Toast.success('Disclaimer accepted successfully!');
      } else {
        Toast.error('Failed to save disclaimer acceptance.');
      }
    } catch (error) {
      console.error(error);
      Toast.error('An error occurred. Please try again.');
    } finally {
      setSubmitting(false);
      adl_legal_pages__modal(false);
    }
  };

  if (showDisclaimer) {
    return (
      <DisclaimerScreen
        onAccept={handleDisclaimerAccept}
        isSubmitting={submitting}
        isLoading={isLoading}
        setIsLoading={setIsLoading}
      />
    );
  }

  if (!acceptedDisclaimer) {
    return null;
  }

  return (
    <div className="mx-auto max-w-5xl px-6 py-10">
      <h2 className="!text-[24px] !font-bold !text-[#17171C]">Setup Wizard</h2>
      <p className="!mt-2 !text-sm !text-[#6F6F7B]">
        Let's get Legal Pages configured for your site in three quick steps
      </p>

      <div className="mt-8">
        <WizardStepper steps={STEPS} currentStep={currentStep} />
      </div>

      <div className="mt-8">
        {currentStep === 1 && (
          <StepBusinessInfo onNext={() => setCurrentStep(2)} onSkip={handleSkip} skipping={skipping} />
        )}

        {currentStep === 2 && (
          <StepCreatePage
            onBack={() => setCurrentStep(1)}
            onCreated={(page) => {
              setCreatedPage(page);
              setCurrentStep(3);
            }}
          />
        )}

        {currentStep === 3 && <StepComplete createdPage={createdPage} />}
      </div>
    </div>
  );
};

export default SetupWizard;
