import React, { useState } from 'react';

const NOTICE_ID = 'cookie_scan';

const CookieIcon = () => (
  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#7C3BED" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
    <path d="M12 2a10 10 0 1 0 10 10 4 4 0 0 1-5-5 4 4 0 0 1-5-5" />
    <path d="M8.5 8.5v.01M16 15.5v.01M12 12v.01M11 17v.01M7 14v.01" />
  </svg>
);

const CloseIcon = () => (
  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" aria-hidden="true">
    <path d="M18 6 6 18M6 6l12 12" />
  </svg>
);

const isDismissed = () => (LEGAL_PAGES?.dismissed_notices || []).includes(NOTICE_ID);

/**
 * Top-of-page notice pointing free users to the Cookie Bar screen's scanner.
 * Hidden once Legal Pages Pro is licensed (`cookie_pro`), while an older Pro is
 * active (its Cookie Bar screen asks for a Pro update instead), and after the
 * current user closes it (stored in user meta via POST /notices/cookie_scan/dismiss).
 * `maxWidth` should match the page's content cards ('' for full-width pages).
 */
const CookieScanNotice = ({ className = '', maxWidth = 'max-w-[1150px]' }) => {
  const [dismissed, setDismissed] = useState(isDismissed);

  if (dismissed || LEGAL_PAGES?.cookie_pro || LEGAL_PAGES?.cookie_legacy_pro) {
    return null;
  }

  const dismiss = () => {
    setDismissed(true);
    // The localized object outlives hash navigation, so other screens see it too.
    LEGAL_PAGES.dismissed_notices = [...(LEGAL_PAGES.dismissed_notices || []), NOTICE_ID];
    fetch(`${LEGAL_PAGES.apiUrl}/notices/${NOTICE_ID}/dismiss`, {
      method: 'POST',
      headers: { 'X-WP-Nonce': LEGAL_PAGES.nonce },
    }).catch(() => {});
  };

  return (
    <div className={`px-8 pt-6 ${className}`}>
      <div className={`relative flex ${maxWidth} flex-col gap-3 rounded-2xl border border-indigo-100 bg-[#7C3BED0D] py-4 pl-5 pr-12 sm:flex-row sm:items-center sm:justify-between`}>
        <div className="flex items-center gap-3">
          <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-[#7C3BED1A]">
            <CookieIcon />
          </span>
          <p className="!m-0 !text-sm !font-medium !text-[#17171C]">
            You can now scan your site to find out which cookie notices you need to display.
          </p>
        </div>
        <a
          href="#/pro-features/cookie-bar"
          className="inline-flex shrink-0 items-center justify-center rounded-xl bg-[#7C3BED] px-5 py-2.5 text-sm !font-bold !text-white no-underline shadow-[0px_4px_14px_-2px_#7C3BED40] transition hover:bg-indigo-700"
        >
          Scan Now
        </a>
        <button
          type="button"
          onClick={dismiss}
          aria-label="Dismiss this notice"
          className="absolute right-3 top-3 flex h-7 w-7 cursor-pointer items-center justify-center rounded-lg border-0 bg-transparent text-[#6F6F7B] transition hover:bg-[#7C3BED1A] hover:text-[#17171C] sm:top-1/2 sm:-translate-y-1/2"
        >
          <CloseIcon />
        </button>
      </div>
    </div>
  );
};

export default CookieScanNotice;
