import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Toast } from '../../../../components/common/Toast';
import SectionCard from '../../../../components/common/SectionCard';
import ToggleField from '../../../../components/common/ToggleField';
import Skeleton from '../../../../components/common/Skeleton';
import { CookieComplianceIcon, GeneralInformationIcon } from '../../../../components/common/SvgIcon';
import ConsentChart, { CHOICES, supportedChoices } from './ConsentChart';

const secondaryBtn =
  'inline-flex cursor-pointer items-center justify-center rounded-xl border border-[#E4E4E7] bg-white px-3.5 py-[11px] text-sm font-medium text-[#17171C] transition hover:bg-[#FAFAFA] disabled:cursor-not-allowed disabled:opacity-50';
const primaryBtn =
  'inline-flex cursor-pointer items-center justify-center rounded-xl bg-[#7C3BED] px-6 py-[11px] text-sm font-semibold text-white shadow-[0px_4px_14px_-2px_#7C3BED40] transition hover:bg-indigo-700 disabled:cursor-not-allowed disabled:bg-indigo-400';
const inputCls =
  '!h-[42px] !rounded-xl !border !border-[#E4E4E7] !bg-white !px-3 !text-sm !text-[#17171C] focus:!border-[#7C3BED] focus:!shadow-none';

const EMPTY_FILTERS = { search: '', from: '', to: '', region: '', action: '' };
const PER_PAGE = 20;

const api = (path, options = {}) =>
  fetch(`${LEGAL_PAGES.apiUrl}${path}`, {
    ...options,
    headers: { 'X-WP-Nonce': LEGAL_PAGES.nonce, ...(options.headers || {}) },
  });

const query = (params) => {
  const qs = new URLSearchParams();
  Object.entries(params).forEach(([k, v]) => v !== '' && v !== null && v !== undefined && qs.set(k, v));
  const s = qs.toString();
  return s ? `?${s}` : '';
};

const choiceLabel = (key) => CHOICES.find((c) => c.key === key)?.label || key;
const choiceColor = (key) => CHOICES.find((c) => c.key === key)?.color || '#A1A1AA';

/**
 * Consent log (Pro): proof of each visitor's consent choices, recorded by the
 * consent banner under the visitor's consent ID. Backend: Legal Pages Pro's
 * `/consent-log*` routes (LegalPagePro\Models\Consent_Log).
 */
const ConsentLog = () => {
  const [settings, setSettings] = useState(null);
  const [savingSettings, setSavingSettings] = useState(false);

  const [filters, setFilters] = useState(EMPTY_FILTERS);
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);

  const [log, setLog] = useState(null);
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const recordsBox = useRef(null);
  const [exporting, setExporting] = useState(false);

  const loadSettings = useCallback(async () => {
    try {
      const res = await api('/consent-log/settings');
      const result = await res.json();
      if (result.success) setSettings(result.data);
    } catch (e) {
      Toast.error('Failed to load consent log settings');
    }
  }, []);

  useEffect(() => { loadSettings(); }, [loadSettings]);

  // Typing in the search box filters after a short pause.
  useEffect(() => {
    const t = setTimeout(() => {
      setFilters((f) => (f.search === search.trim() ? f : { ...f, search: search.trim() }));
    }, 350);
    return () => clearTimeout(t);
  }, [search]);

  useEffect(() => { setPage(1); }, [filters]);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    Promise.all([
      api(`/consent-log${query({ ...filters, page, per_page: PER_PAGE })}`).then((r) => r.json()),
      api(`/consent-log/stats${query(filters)}`).then((r) => r.json()),
    ])
      .then(([list, st]) => {
        if (cancelled) return;
        if (list.success) setLog(list.data);
        if (st.success) setStats(st.data);
      })
      .catch(() => !cancelled && Toast.error('Failed to load the consent log'))
      .finally(() => !cancelled && setLoading(false));
    return () => { cancelled = true; };
  }, [filters, page]);

  // A new page or filter starts at the top of the records box, not where the last one was scrolled to.
  useEffect(() => {
    if (recordsBox.current) recordsBox.current.scrollTop = 0;
  }, [log]);

  const setFilter = (key, value) => setFilters((f) => ({ ...f, [key]: value }));

  const resetFilters = () => {
    setSearch('');
    setFilters(EMPTY_FILTERS);
  };

  const saveSettings = async () => {
    setSavingSettings(true);
    try {
      const res = await api('/consent-log/settings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ enabled: settings.enabled, retention_months: settings.retention_months }),
      });
      const result = await res.json();
      if (result.success) {
        setSettings(result.data);
        Toast.success('Consent log settings saved!');
      } else {
        Toast.error('Failed to save settings.');
      }
    } catch (e) {
      Toast.error('An error occurred while saving.');
    } finally {
      setSavingSettings(false);
    }
  };

  // The export route streams CSV, so it's downloaded as a file, not parsed.
  const exportCsv = async () => {
    setExporting(true);
    try {
      const res = await api(`/consent-log/export${query(filters)}`);
      if (!res.ok) throw new Error(String(res.status));
      const blob = await res.blob();
      const match = /filename="([^"]+)"/.exec(res.headers.get('Content-Disposition') || '');
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = match ? match[1] : 'consent-log.csv';
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
    } catch (e) {
      Toast.error('Export failed.');
    } finally {
      setExporting(false);
    }
  };

  const hasFilters = Object.values(filters).some((v) => v !== '') || search !== '';

  return (
    <div className="space-y-6">
      {/* ── Settings ── */}
      <SectionCard title="Proof of Consent" icon={<CookieComplianceIcon />} maxHeight="">
        {!settings ? <Skeleton /> : (
          <div className="space-y-4">
            <p className="!text-sm !text-[#6F6F7B]">
              Every Accept, Deny and Save preferences in the consent banner is recorded with the visitor's consent ID,
              the time, the categories they accepted, the banner and cookie policy versions they saw, and their region.
              Opt-outs (the Opt out button and "Do Not Sell or Share") and Global Privacy Control signals honored
              automatically are recorded too.
              Visitors see their consent ID under View preferences, so you can look them up here. No IP addresses are stored.
            </p>

            <ToggleField
              label="Record consents"
              description="Keep a log of every consent choice made in the banner"
              name="enabled"
              checked={settings.enabled}
              onChange={(name, value) => setSettings((s) => ({ ...s, [name]: value }))}
            />

            <div className="flex flex-wrap items-end gap-4">
              <label className="flex flex-col gap-1.5 text-sm font-medium text-[#17171C]">
                Keep records for
                <select
                  className={`${inputCls} !pr-8`}
                  value={settings.retention_months}
                  onChange={(e) => setSettings((s) => ({ ...s, retention_months: Number(e.target.value) }))}
                >
                  {settings.retention_choices.map((m) => (
                    <option key={m} value={m}>{m} {m === 1 ? 'month' : 'months'}</option>
                  ))}
                </select>
              </label>
              <button type="button" className={primaryBtn} onClick={saveSettings} disabled={savingSettings}>
                {savingSettings ? 'Saving...' : 'Save Settings'}
              </button>
            </div>
            <p className="!text-xs !text-[#6F6F7B]">Older records are deleted automatically once a day.</p>

            <dl className="grid grid-cols-2 gap-3 border-t border-[#F4F4F5] pt-4 text-sm md:grid-cols-4">
              <div>
                <dt className="text-xs text-[#6F6F7B]">Records stored</dt>
                <dd className="font-semibold text-[#17171C]">{settings.total_rows.toLocaleString()}</dd>
              </div>
              <div>
                <dt className="text-xs text-[#6F6F7B]">Oldest record</dt>
                <dd className="font-semibold text-[#17171C]">{settings.oldest || '—'}</dd>
              </div>
              <div>
                <dt className="text-xs text-[#6F6F7B]">Current banner version</dt>
                <dd className="font-semibold text-[#17171C]" title="Goes up when the banner texts, categories or policy link change">
                  v{settings.banner_version}
                </dd>
              </div>
              <div>
                <dt className="text-xs text-[#6F6F7B]">Cookie policy version</dt>
                <dd className="font-semibold text-[#17171C]" title="When the linked cookie policy page was last updated (UTC)">
                  {settings.policy_version || 'Not a page on this site'}
                </dd>
              </div>
            </dl>
          </div>
        )}
      </SectionCard>

      {/* ── Filters ── */}
      <div className="flex max-w-[1150px] flex-wrap items-end gap-3">
        <label className="flex min-w-[240px] flex-1 flex-col gap-1.5 text-xs font-medium text-[#6F6F7B]">
          Consent ID
          <input
            type="search"
            className={`${inputCls} font-mono`}
            placeholder="Search by consent ID"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </label>
        <label className="flex flex-col gap-1.5 text-xs font-medium text-[#6F6F7B]">
          From
          <input type="date" className={inputCls} value={filters.from} max={filters.to || undefined} onChange={(e) => setFilter('from', e.target.value)} />
        </label>
        <label className="flex flex-col gap-1.5 text-xs font-medium text-[#6F6F7B]">
          To
          <input type="date" className={inputCls} value={filters.to} min={filters.from || undefined} onChange={(e) => setFilter('to', e.target.value)} />
        </label>
        <label className="flex flex-col gap-1.5 text-xs font-medium text-[#6F6F7B]">
          Region
          <select className={`${inputCls} !pr-8`} value={filters.region} onChange={(e) => setFilter('region', e.target.value)}>
            <option value="">All regions</option>
            {(log?.regions || []).map((r) => <option key={r} value={r}>{r}</option>)}
          </select>
        </label>
        <label className="flex flex-col gap-1.5 text-xs font-medium text-[#6F6F7B]">
          Choice
          <select className={`${inputCls} !pr-8`} value={filters.action} onChange={(e) => setFilter('action', e.target.value)}>
            <option value="">All choices</option>
            {supportedChoices(stats).map((c) => <option key={c.key} value={c.key}>{c.label}</option>)}
          </select>
        </label>
        {hasFilters && (
          <button type="button" className={secondaryBtn} onClick={resetFilters}>Reset</button>
        )}
        <button type="button" className={primaryBtn} onClick={exportCsv} disabled={exporting || !log?.total}>
          {exporting ? 'Exporting...' : 'Export CSV'}
        </button>
      </div>

      {/* ── Chart ── */}
      <SectionCard title="Accept / Deny Rate" icon={<GeneralInformationIcon />} maxHeight="">
        {!stats ? <Skeleton /> : <ConsentChart stats={stats} />}
      </SectionCard>

      {/* ── Records ── */}
      <SectionCard title={`Consent Records${log ? ` (${log.total.toLocaleString()})` : ''}`} icon={<CookieComplianceIcon />} maxHeight="">
        {!log ? <Skeleton /> : (
          <div className={loading ? 'opacity-60 transition-opacity' : 'transition-opacity'}>
            {/* Same scroll box as the cookie scanner's results table. */}
            <div className="overflow-hidden rounded-xl border border-[#E4E4E7]">
            <div ref={recordsBox} className="max-h-[420px] overflow-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-[#E4E4E7] bg-[#FAFAFA]">
                    <th className="px-4 py-3 text-left font-semibold text-[#17171C]">Date</th>
                    <th className="px-4 py-3 text-left font-semibold text-[#17171C]">Consent ID</th>
                    <th className="px-4 py-3 text-left font-semibold text-[#17171C]">Choice</th>
                    <th className="px-4 py-3 text-left font-semibold text-[#17171C]">Categories</th>
                    <th className="px-4 py-3 text-left font-semibold text-[#17171C]">Banner</th>
                    <th className="px-4 py-3 text-left font-semibold text-[#17171C]">Policy</th>
                    <th className="px-4 py-3 text-left font-semibold text-[#17171C]">Region</th>
                    <th className="px-4 py-3 text-left font-semibold text-[#17171C]">Page</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[#E4E4E7]">
                  {log.items.length === 0 && (
                    <tr>
                      <td colSpan={8} className="px-4 py-10 text-center text-[#6F6F7B]">
                        {hasFilters ? 'No records match these filters.' : 'No consents recorded yet. They appear here as visitors use the consent banner.'}
                      </td>
                    </tr>
                  )}
                  {log.items.map((row) => (
                    <tr key={row.id} className="hover:bg-[#FAFAFA]">
                      <td className="whitespace-nowrap px-4 py-3 text-[#3F3F46]" title={`${row.created_at} (UTC)`}>{row.created_local}</td>
                      <td className="whitespace-nowrap px-4 py-3">
                        <button
                          type="button"
                          className="cursor-pointer whitespace-nowrap font-mono text-xs text-[#7C3BED] hover:underline"
                          title="Show every choice for this consent ID"
                          onClick={() => setSearch(row.consent_id)}
                        >
                          {row.consent_id}
                        </button>
                      </td>
                      <td className="whitespace-nowrap px-4 py-3 text-[#17171C]">
                        <span className="inline-flex items-center gap-1.5">
                          <span className="inline-block h-2.5 w-2.5 rounded-sm" style={{ background: choiceColor(row.action) }} />
                          {choiceLabel(row.action)}
                        </span>
                      </td>
                      <td className="px-4 py-3 text-[#3F3F46]">{row.categories.join(', ')}</td>
                      <td className="px-4 py-3 text-[#3F3F46]">{row.banner_version ? `v${row.banner_version}` : '—'}</td>
                      <td className="whitespace-nowrap px-4 py-3 text-[#3F3F46]">{row.policy_version || '—'}</td>
                      <td className="px-4 py-3 text-[#3F3F46]">{row.region || '—'}</td>
                      <td className="max-w-[200px] truncate px-4 py-3 text-[#3F3F46]" title={row.url}>{row.url}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            </div>

            {log.total_pages > 1 && (
              <div className="mt-4 flex items-center justify-between text-sm text-[#6F6F7B]">
                <span>Page {log.page} of {log.total_pages.toLocaleString()}</span>
                <div className="flex gap-2">
                  <button type="button" className={secondaryBtn} disabled={page <= 1 || loading} onClick={() => setPage((p) => p - 1)}>Previous</button>
                  <button type="button" className={secondaryBtn} disabled={page >= log.total_pages || loading} onClick={() => setPage((p) => p + 1)}>Next</button>
                </div>
              </div>
            )}
          </div>
        )}
      </SectionCard>
    </div>
  );
};

export default ConsentLog;
