import React, { useState } from 'react';

import { AddedTemplateIcon, ViewIcon, EditIcon, ArrowRightIcon } from '../../../components/common/SvgIcon';

const StepComplete = ({ createdPage }) => {
  const [finishing, setFinishing] = useState(false);

  const handleFinish = async () => {
    setFinishing(true);
    try {
      await fetch(`${LEGAL_PAGES.apiUrl}/setup-wizard/complete`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-WP-Nonce': LEGAL_PAGES.nonce,
        },
      });
    } catch (error) {
      console.error('Error completing setup wizard:', error);
    } finally {
      setFinishing(false);
      window.location.hash = '/all-legal-pages';
    }
  };

  return (
    <div className="mx-auto max-w-2xl rounded-2xl border border-[#E4E4E780] bg-white p-10 text-center shadow-[0_4px_6px_-4px_rgba(0,0,0,0.08),0_10px_15px_-3px_rgba(0,0,0,0.08)]">
      <div className="mx-auto grid h-16 w-16 place-items-center rounded-full bg-[#7C3BED]">
        <AddedTemplateIcon />
      </div>

      <h2 className="mt-6 text-xl font-bold text-[#17171C]">You're all set!</h2>

      {createdPage?.title ? (
        <p className="mt-2 text-sm text-[#6F6F7B]">
          "{createdPage.title}" has been published. You can create more legal pages any time from{' '}
          <span className="font-medium text-[#17171C]">Legal Pages &rarr; Add New Legal Page</span>.
        </p>
      ) : (
        <p className="mt-2 text-sm text-[#6F6F7B]">
          Legal Pages is ready to use. You can create legal pages any time from{' '}
          <span className="font-medium text-[#17171C]">Legal Pages &rarr; Add New Legal Page</span>.
        </p>
      )}

      {createdPage && (
        <div className="mt-6 flex items-center justify-center gap-3">
          <a
            href={createdPage.view_url}
            target="_blank"
            rel="noopener noreferrer"
            className="inline-flex items-center gap-2 rounded-xl border border-[#E4E4E7] px-5 py-3 text-sm !font-bold text-[#17171C] hover:bg-gray-50"
          >
            <ViewIcon />
            View Page
          </a>
          <a
            href={createdPage.edit_url}
            target="_blank"
            rel="noopener noreferrer"
            className="inline-flex items-center gap-2 rounded-xl border border-[#E4E4E7] px-5 py-3 text-sm !font-bold text-[#17171C] hover:bg-gray-50"
          >
            <EditIcon />
            Edit Page
          </a>
        </div>
      )}

      <button
        type="button"
        onClick={handleFinish}
        disabled={finishing}
        className={[
          'mt-8 inline-flex items-center justify-center gap-2 rounded-xl px-8 py-[14px] text-sm !font-bold text-white shadow-[0px_4px_14px_-2px_#7C3BED40] transition',
          finishing ? 'cursor-not-allowed bg-indigo-400' : 'bg-[#7C3BED] hover:bg-indigo-700',
        ].join(' ')}
      >
        Go to All Legal Pages
        <ArrowRightIcon />
      </button>
    </div>
  );
};

export default StepComplete;
