import React from 'react';

const CrownBadge = () => (
  <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-[#7C3BED1A] text-lg">
    👑
  </span>
);

const CloseIcon = () => (
  <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
  </svg>
);

const ArrowIcon = () => (
  <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7l5 5m0 0l-5 5m5-5H6" />
  </svg>
);

/**
 * Small "this is a Pro feature" popover shown when a locked Pro item
 * (e.g. a Pro template row) is clicked, instead of just disabling it.
 * Caller is responsible for positioning (wrap in a `relative`/`absolute`
 * anchor) and for closing it on outside click.
 */
const ProFeaturePopover = ({
  title = 'This is a Pro Feature',
  description,
  onClose,
  ctaLabel = 'Upgrade to Pro',
  ctaHref = 'https://legalpagespro.com/?utm_source=lite-plugin#pricing',
  className = '',
}) => (
  <div
    onClick={(e) => e.stopPropagation()}
    className={`relative w-[300px] rounded-2xl border border-[#E4E4E7] bg-white p-5 text-left shadow-[0_10px_30px_-5px_rgba(0,0,0,0.15)] ${className}`}
  >
    <button
      type="button"
      onClick={onClose}
      aria-label="Close"
      className="absolute right-4 top-4 text-gray-400 transition-colors hover:text-gray-600"
    >
      <CloseIcon />
    </button>

    <CrownBadge />

    <h4 className="!mb-1.5 !mt-3 !text-[15px] !font-semibold !text-[#17171C]">{title}</h4>
    <p className="!mb-4 !text-[13px] !leading-[19px] !text-[#6F6F7B]">{description}</p>

    <a
      href={ctaHref}
      target="_blank"
      rel="noopener noreferrer"
      onClick={(e) => e.stopPropagation()}
      className="inline-flex items-center gap-2 rounded-xl bg-[#7C3BED] px-4 py-2.5 text-sm font-semibold !text-white no-underline transition hover:bg-indigo-700"
    >
      {ctaLabel}
      <ArrowIcon />
    </a>
  </div>
);

export default ProFeaturePopover;
