import React, { useState, useEffect, useCallback } from 'react';
import MainPageLayout from '../../components/common/MainPageLayout';
import ProFeaturePoster from '../../components/common/ProFeaturePoster';
import ProFeatureModal,{ LockIcon } from '../../components/common/ProFeatureModal';
import GCookieSettings from './components/GCookieSettings';
import BlockServices from './components/BlockServices';
import CookieScanner from './components/CookieScanner';
import ConsentLog from './components/ConsentLog';
import Regions from './components/Regions';
import { CookieBlock, CookieComplianceIcon, GeneralInformationIcon, GlobeIcon } from '../../components/common/SvgIcon';

const PRO_MESSAGES = {
  default: 'This feature is available in Legal Pages Pro. Upgrade to unlock it.',
  banner: 'Showing a cookie consent banner on your website (with Google Consent Mode v2 and a Manage consent button) is available in Legal Pages Pro.',
  post_types: 'Scanning products, docs and other custom post types is available in Legal Pages Pro.',
  sync: 'Re-syncing cookie descriptions with cookiedatabase.org is available in Legal Pages Pro.',
  clear: 'Clearing scanned cookies is available in Legal Pages Pro.',
  category: 'Changing a cookie\'s category is available in Legal Pages Pro.',
  ignore: 'Hiding cookies from your cookie policy (Ignore / Restore) is available in Legal Pages Pro.',
  block_services: 'Blocking third-party scripts until visitors consent is available in Legal Pages Pro.',
  customize: 'Customizing the cookie bar position, consent categories, texts and colors is available in Legal Pages Pro.',
  consent_log: 'Keeping a log of visitors\' consent choices (proof of consent) with CSV export is available in Legal Pages Pro.',
  regions: 'Showing each visitor the banner their region\'s law expects (opt-in, opt-out or notice), and honoring Global Privacy Control, is available in Legal Pages Pro.',
};

/**
 * `locked` (no Pro, or no valid license): scanning and the cookie list work;
 * the consent banner and everything else is shown with a lock and opens the
 * Pro modal. The banner itself is Legal Pages Pro's code
 * (LegalPagePro\Controllers\Front\ConsentBanner), and the settings are only
 * saved through Pro (see LegalPage\Models\Cookie_Bar).
 */
const CookieSettings = ({ locked = false }) => {
  const [activeTab, setActiveTab] = useState(() => {
    try {
      return localStorage.getItem('legal_pages_cookie_settings_tab') || 'general';
    } catch (e) {
      return 'general';
    }
  });
  const [isLoading, setIsLoading] = useState(false);
  const [proModal, setProModal] = useState(null);

  const showPro = useCallback((feature = 'default') => setProModal(feature), []);
  const closePro = useCallback(() => setProModal(null), []);

  const currentTab = locked ? 'general' : activeTab;

  useEffect(() => {
    try {
      localStorage.setItem('legal_pages_cookie_settings_tab', activeTab);
    } catch (e) {}
  }, [activeTab]);

  // Pro before 2.1.0 still runs its own cookie bar, and the free scanner and
  // settings routes are off (legal_pages_cookie_bar_in_legacy_pro()).
  const legacyPro = LEGAL_PAGES?.cookie_legacy_pro;
  if (legacyPro) {
    return (
      <MainPageLayout
        title="Cookie Bar Settings"
        description="Configure EU cookie consent bar for GDPR compliance"
      >
        <div className="mt-6 flex max-w-[1150px] flex-col gap-5 rounded-2xl border border-amber-200 bg-amber-50 p-6 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <h3 className="!mb-1 !text-[16px] !font-semibold !text-[#17171C]">Update Legal Pages Pro to use the new Cookie Bar</h3>
            <p className="!text-sm !text-[#6F6F7B]">
              {`You have Legal Pages Pro ${legacyPro.version || ''}`.trim()}. The cookie scanner and the new cookie settings need
              Legal Pages Pro 2.1.0 or newer. Your current cookie banner keeps working, and your settings carry over after the update.
            </p>
          </div>
          {legacyPro.update_url && (
            <a
              href={legacyPro.update_url}
              className="inline-flex shrink-0 items-center gap-2 whitespace-nowrap rounded-xl bg-[#7C3BED] px-5 py-3 text-sm font-semibold !text-white no-underline transition hover:bg-indigo-700"
            >
              Update Legal Pages Pro
            </a>
          )}
        </div>
      </MainPageLayout>
    );
  }

  const tabs = [
    { id: 'general', label: 'General Settings', icon: (<GeneralInformationIcon />) },
    { id: 'block_services', label: 'Block Services', icon: (<CookieBlock />), pro: true },
    { id: 'consent_log', label: 'Consent Log', icon: (<CookieComplianceIcon />), pro: true },
    { id: 'regions', label: 'Regions', icon: (<GlobeIcon />), pro: true },
  ];

  return (
    <MainPageLayout
      title="Cookie Bar Settings"
      description="Configure EU cookie consent bar for GDPR compliance"
    >
      {/* Locked: settings on the left, the upgrade poster in a sticky right column
          (on narrower screens it sits above the settings instead). */}
      <div className={locked ? 'grid grid-cols-1 gap-6 xl:grid-cols-[minmax(0,1fr)_300px] xl:items-start' : ''}>
      {locked && (
        <aside className="xl:order-last xl:sticky xl:top-[52px]">
          <ProFeaturePoster
            title="Cookie Bar is a Pro Feature"
            description="Show a cookie consent banner, block third-party scripts until visitors consent, and customize its texts and colors. Upgrade to Pro to unlock this feature and get more control over your legal pages."
          />
        </aside>
      )}

      <div className="min-w-0">
      <div className={locked ? '' : 'mt-6'}>
        <CookieScanner locked={locked} onLocked={showPro} />
      </div>

      {/* Tabs */}
      <div className="mt-6 mb-6">
        <div className="inline-flex rounded-xl bg-[#F4F4F5] p-[4px]">
          {tabs.map((tab) => {
            const tabLocked = locked && tab.pro;
            return (
              <button
                key={tab.id}
                onClick={() => (tabLocked ? showPro(tab.id) : setActiveTab(tab.id))}
                className={[
                  'relative flex cursor-pointer items-center gap-2 rounded-xl px-6 py-3 text-sm font-medium transition',
                  currentTab === tab.id
                    ? 'bg-white text-[#17171C] shadow-[0px_1px_2px_0px_#0000000D] ring-1 ring-gray-200'
                    : 'text-gray-600 hover:text-gray-900',
                ].join(' ')}
              >
                {tab.icon}
                {tab.label}
                {tabLocked && <span className="text-[#7C3BED]"><LockIcon /></span>}
              </button>
            );
          })}
        </div>
      </div>

      {currentTab === 'general' && (
        <GCookieSettings isLoading={isLoading} setIsLoading={setIsLoading} locked={locked} onLocked={showPro} />
      )}
      {currentTab === 'block_services' && (
        <BlockServices isLoading={isLoading} setIsLoading={setIsLoading} />
      )}
      {currentTab === 'consent_log' && <ConsentLog />}
      {currentTab === 'regions' && <Regions />}
      </div>
      </div>

      <ProFeatureModal
        isOpen={proModal !== null}
        onClose={closePro}
        title="This is a Pro Feature"
        description={PRO_MESSAGES[proModal] || PRO_MESSAGES.default}
      />
    </MainPageLayout>
  );
};

export default CookieSettings;
