import React from 'react';

const LockCircleIcon = () => (
  <span className="flex h-16 w-16 items-center justify-center rounded-full bg-[#7C3BED1A]">
    <svg className="h-7 w-7" viewBox="0 0 24 24" fill="none" stroke="#7C3BED" strokeWidth="2">
      <rect x="4" y="10" width="16" height="10" rx="2" strokeLinecap="round" strokeLinejoin="round" />
      <path d="M7 10V7a5 5 0 0110 0v3" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  </span>
);

const ArrowIcon = () => (
  <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7l5 5m0 0l-5 5m5-5H6" />
  </svg>
);

/**
 * Renders `children` for real (unmodified) when `active` is false.
 * When `active` is true, renders the same `children` blurred and inert
 * behind a centered "Upgrade" overlay, so a non-Pro user sees a live
 * preview of the feature instead of a disabled/blocked screen.
 */
const ProFeatureLock = ({
  active,
  title,
  description,
  ctaLabel = 'Upgrade to Pro',
  ctaHref = 'https://legalpagespro.com/?utm_source=lite-plugin#pricing',
  // 'sticky' pins the overlay near the top of the viewport while scrolling, for
  // previews taller than the screen (centered, it would land below the fold).
  overlay = 'center',
  children,
}) => {
  if (!active) {
    return children;
  }

  const sticky = overlay === 'sticky';

  return (
    <div className="relative max-w-[1150px]">
      <div aria-hidden="true" className="pointer-events-none select-none blur-[8px] opacity-50">
        {children}
      </div>

      <div className={`absolute inset-0 z-10 flex flex-col items-center ${sticky ? 'justify-start pt-12' : 'justify-center'} px-4 text-center`}>
        <div className={`flex flex-col items-center gap-4 ${sticky ? 'sticky top-[30vh]' : ''}`}>
          <LockCircleIcon />

          <div className="max-w-[420px]">
            <h4 className="!mb-2 !text-[18px] !font-bold !text-[#17171C]">{title}</h4>
            <p className="!text-sm !text-[#6F6F7B]">{description}</p>
          </div>

          <a
            href={ctaHref}
            target="_blank"
            rel="noopener noreferrer"
            className="inline-flex items-center gap-2 rounded-xl bg-[#7C3BED] px-6 py-3 text-sm font-semibold !text-white no-underline shadow-[0px_4px_14px_-2px_#7C3BED40] transition hover:bg-indigo-700"
          >
            {ctaLabel}
            <ArrowIcon />
          </a>
        </div>
      </div>
    </div>
  );
};

export default ProFeatureLock;
