import React, { useEffect, useState } from 'react';

/**
 * Black Friday 2026 campaign UI (temporary — remove after the sale).
 *
 * `LEGAL_PAGES_PROMO` is printed by `Controllers\Admin\Promo` only while the sale
 * runs (15 Nov – 5 Dec 2026, site time) and only for admins without a valid
 * license. `usePromo()` returns null outside that window, and also once the
 * countdown reaches zero on an open tab, so every caller falls back to its
 * normal upgrade UI by itself.
 */

const readPromo = () => (typeof window !== 'undefined' && window.LEGAL_PAGES_PROMO) || null;

const pad = (n) => String(n).padStart(2, '0');

export const usePromo = () => {
  const promo = readPromo();
  const [now, setNow] = useState(() => Date.now());

  useEffect(() => {
    if (!promo) return undefined;
    const timer = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(timer);
  }, [promo]);

  if (!promo || now < promo.start * 1000 || now >= promo.end * 1000) {
    return null;
  }

  const left = Math.floor((promo.end * 1000 - now) / 1000);
  const parts = {
    d: pad(Math.floor(left / 86400)),
    h: pad(Math.floor((left % 86400) / 3600)),
    m: pad(Math.floor((left % 3600) / 60)),
    s: pad(left % 60),
  };

  return {
    ...promo,
    parts,
    // "05d 14h 22m 09s"
    leftText: `${parts.d}d ${parts.h}h ${parts.m}m ${parts.s}s`,
    off: `${promo.discount}%`,
  };
};

const isDismissed = (id) => (readPromo()?.dismissed || []).includes(id);

const dismissNotice = (id) => {
  const promo = readPromo();
  if (promo) {
    promo.dismissed = [...(promo.dismissed || []), id];
  }
  fetch(`${LEGAL_PAGES.apiUrl}/notices/${id}/dismiss`, {
    method: 'POST',
    headers: { 'X-WP-Nonce': LEGAL_PAGES.nonce },
  }).catch(() => {});
};

const useDismissible = (id) => {
  const [dismissed, setDismissed] = useState(() => isDismissed(id));
  return [dismissed, () => { setDismissed(true); dismissNotice(id); }];
};

