/** "05d 14h 22m 09s" as chips. `tone`: 'purple' (on dark) or 'dark' (on light). */
export const CountdownChips = ({ parts, tone = 'purple' }) => {
  const chip = tone === 'dark'
    ? 'bg-[#17171C] text-white'
    : 'bg-[#5B21B6] text-white';

  return (
    <span className="inline-flex items-center gap-1.5" role="timer" aria-label={`${parts.d} days ${parts.h} hours ${parts.m} minutes ${parts.s} seconds left`}>
      {[['d', parts.d], ['h', parts.h], ['m', parts.m], ['s', parts.s]].map(([unit, value]) => (
        <span key={unit} className={`rounded-md px-2 py-1 text-sm font-bold tabular-nums ${chip}`}>
          {value}{unit}
        </span>
      ))}
    </span>
  );
};

const darkCard = 'bg-[#17171C] bg-[radial-gradient(circle_at_88%_0%,rgba(124,59,237,0.55),transparent_45%),radial-gradient(circle_at_0%_110%,rgba(124,59,237,0.3),transparent_40%)]';
export const promoDarkCard = darkCard;

/**
 * Slim strip at the top of most screens. `maxWidth` should match the page's
 * content ('' for full-width pages).
 */
export const PromoBar = ({ maxWidth = '' }) => {
  const promo = usePromo();
  const [dismissed, dismiss] = useDismissible('bf_2026_bar');

  if (!promo || dismissed) return null;

  return (
    <div className="px-8 pt-6">
      <div className={`relative flex ${maxWidth} flex-col gap-3 rounded-2xl bg-[#17171C] py-3.5 pl-6 pr-12 shadow-[0_12px_30px_-14px_rgba(23,23,28,0.6)] xl:flex-row xl:items-center xl:justify-between`}>
        <div className="flex flex-wrap items-center gap-x-6 gap-y-1">
          <span className="inline-flex items-center gap-2 text-[13px] font-extrabold uppercase tracking-[0.14em] text-[#FCD34D]">
            <BoltIcon /> Black Friday
          </span>
          <p className="!m-0 !text-sm !text-[#E4E4E7]">
            Get <strong className="!font-bold text-white">Legal Pages Pro for {promo.off} off</strong>, lifetime plans included. Ends {promo.ends_label}.
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-4">
          <CountdownChips parts={promo.parts} />
          <PromoButton promo={promo}>Claim {promo.off} off</PromoButton>
        </div>
        <button
          type="button"
          onClick={dismiss}
          aria-label="Dismiss the Black Friday notice"
          className="absolute right-3 top-3 flex h-7 w-7 cursor-pointer items-center justify-center rounded-lg border-0 bg-transparent text-[#A1A1AA] transition hover:bg-white/10 hover:text-white xl:top-1/2 xl:-translate-y-1/2"
        >
          <CloseIcon />
        </button>
      </div>
    </div>
  );
};

