import React from 'react';
import { AddedTemplateIcon } from '../../../components/common/SvgIcon';

const WizardStepper = ({ steps, currentStep }) => {
  return (
    <div className="flex items-center">
      {steps.map((step, index) => {
        const isCompleted = step.id < currentStep;
        const isActive = step.id === currentStep;

        return (
          <React.Fragment key={step.id}>
            <div className="flex items-center gap-3">
              <span
                className={[
                  'grid h-9 w-9 flex-shrink-0 place-items-center rounded-full text-sm font-semibold transition',
                  isCompleted
                    ? 'bg-[#7C3BED] text-white'
                    : isActive
                    ? 'border-2 border-[#7C3BED] text-[#7C3BED]'
                    : 'border-2 border-[#E4E4E7] text-[#6F6F7B]',
                ].join(' ')}
              >
                {isCompleted ? <AddedTemplateIcon /> : step.id}
              </span>

              <span
                className={[
                  'text-sm font-medium',
                  isActive || isCompleted ? 'text-[#17171C]' : 'text-[#6F6F7B]',
                ].join(' ')}
              >
                {step.label}
              </span>
            </div>

            {index < steps.length - 1 && (
              <div
                className={[
                  'mx-4 h-[2px] flex-1',
                  isCompleted ? 'bg-[#7C3BED]' : 'bg-[#E4E4E7]',
                ].join(' ')}
              />
            )}
          </React.Fragment>
        );
      })}
    </div>
  );
};

export default WizardStepper;
